Object.assign(GL,{"chemorec":{"t":"化學感受器 chemoreceptors","d":"偵測化學物質的感受器：味蕾、嗅覺，以及偵測血中 O₂、CO₂、pH 的頸動脈體與主動脈體。","c":"10.1；第 16 章","f":"化學物質與受體或通道結合 → 產生電訊號。外部：味覺、嗅覺。內部：頸動脈體與主動脈體（周邊，主要偵測 O₂↓）、延腦（中樞，偵測 CSF 的 H⁺／CO₂）→ 調節呼吸。","m":"<b>化學感受器：舌、鼻、血液</b>。","en":"chemoreceptor|化學感受器;taste|味覺;smell|嗅覺;carotid body|頸動脈體"},
"photorec":{"t":"光感受器 photoreceptors","d":"偵測光的感受器：視網膜的桿細胞與錐細胞。","c":"10.7","f":"感光色素吸收光子 → 改變形狀 → G 蛋白連鎖反應 → 膜電位改變。桿細胞負責暗處、錐細胞負責顏色與細節。","e":"維生素 A 是感光色素的必需原料。","m":"<b>桿看暗、錐看色</b>。","en":"photoreceptor|光感受器;rods|桿細胞;cones|錐細胞"},
"mechanorec":{"t":"機械感受器 mechanoreceptors","d":"偵測觸、壓、牽張、振動、聲音、重力的感受器。","c":"10.1","f":"機械力使細胞膜或纖毛變形 → 打開機械閘控離子通道 → 去極化。包括皮膚觸壓覺、肌梭與肌腱、內耳毛細胞（聽覺與平衡）、血管的壓力感受器。","m":"<b>拉、壓、彎 → 開通道</b>。","en":"mechanoreceptor|機械感受器;touch|觸覺;pressure|壓力;hair cell|毛細胞"},
"nocirec":{"t":"痛覺（傷害）感受器 nociceptors","d":"偵測組織損傷或可能造成損傷的刺激（極端溫度、壓力、化學物質）的游離神經末梢。","c":"10.1、10.2","f":"多為游離神經末梢；強烈刺激與發炎物質（前列腺素、緩激肽、組織胺、H⁺、K⁺）使其敏感化。訊號經有髓鞘的 Aδ 纖維（快、刺痛、定位清楚）與無髓鞘的 C 纖維（慢、灼熱痛、定位模糊）傳入。","e":"NSAIDs 減少前列腺素，降低痛覺感受器的敏感化而止痛。","m":"<b>Aδ 快刺、C 慢燒</b>。","en":"nociceptor|痛覺感受器;pain|痛覺;tissue damage|組織損傷;free nerve endings|游離神經末梢"},
"thermorec":{"t":"溫度感受器 thermoreceptors","d":"皮膚中專門偵測「冷」與「熱」的感覺神經末梢。","c":"10.2","f":"TRPV1：熱（約 43°C 以上）與辣椒素；TRPM8：涼與薄荷醇。對溫度「變化」最敏感，持續同溫度會適應。","e":"薄荷讓人覺得涼、辣椒讓人覺得熱，就是化學物質直接打開溫度感受器的通道。","m":"<b>辣 → TRPV1（熱）；薄荷 → TRPM8（涼）</b>。","en":"thermoreceptor|溫度感受器;warm receptor|溫覺受器;cold receptor|冷覺受器;TRPV1|辣椒素受體"},
"lsne":{"t":"特定神經能量定律 law of specific nerve energies","d":"不論用什麼方式刺激，同一條感覺路徑傳到腦都只產生同一種感覺。","e":"眼睛被打一拳會「看到金星」——壓力刺激視網膜，大腦仍解讀成光。","c":"10.1","f":"感覺的「種類」不是由刺激決定，而是由被活化的感覺路徑與它到達的皮質區域決定。","m":"<b>走哪條線，就是哪種感覺</b>。","en":"law of specific nerve energies|特定神經能量定律;sensory modality|感覺模式"},
"adequate":{"t":"適當刺激 adequate stimulus","d":"感受器最敏感的那一種刺激（如視網膜對光）。","c":"10.1","f":"每種感受器對某一種能量的閾值最低；其他刺激需要非常強才能引起反應。","e":"光是視網膜的適當刺激；聲波是耳蝸毛細胞的適當刺激。","m":"<b>每種感受器都有最愛的刺激</b>。","en":"adequate stimulus|適當刺激;threshold|閾值"},
"transduc":{"t":"轉導 transduction","d":"感受器把外界的能量（光、聲、壓力、化學物質）翻譯成神經能懂的電訊號。","c":"10.1","f":"刺激 → 受體或通道改變 → 離子流動 → 發生器電位（分級）→ 達閾值 → 感覺神經的動作電位。","m":"<b>轉導＝翻譯成電</b>。","en":"sensory transduction|感覺轉導;stimulus energy|刺激能量;receptor potential|受器電位"},
"genpot":{"t":"發生器電位 generator potential","d":"感受器受刺激產生的分級去極化；越強越大，達閾值時在感覺神經上產生動作電位，頻率代表強度。","c":"10.1","f":"刺激越強，發生器電位越大 → 動作電位頻率越高；所以感覺強度是以「頻率」編碼。","m":"<b>強度 → 電位大小 → 發射頻率</b>。","en":"generator potential|發生器電位;receptor potential|受器電位;graded potential|分級電位"},
"tonicrec":{"t":"緊張性、相位性感受器 tonic / phasic receptors","d":"<b>緊張性</b>：刺激持續時持續放電（痛覺、肌梭）。<b>相位性</b>：只在刺激開始（與結束）時放電，很快適應（觸壓覺、嗅覺）。","c":"10.1","f":"<b>緊張性</b>：慢適應，持續報告刺激還在（痛覺、肌梭、壓力感受器、本體感覺）。<b>相位性</b>：快適應，只在刺激開始或改變時放電（觸覺的梅斯納小體、巴齊尼小體、嗅覺）。","e":"戴上手錶不久就感覺不到它（相位性）；但痛不會因為持續就消失（緊張性），以免忽略傷害。","m":"<b>緊張性一直報、相位性報變化</b>。","en":"tonic receptor|緊張性感受器;phasic receptor|相位性感受器;slowly adapting|慢適應;rapidly adapting|快適應"},
"adaptation":{"t":"適應 adaptation","d":"持續相同刺激下感受器反應逐漸減少，使我們忽略不變的背景、注意變化。","c":"10.1","f":"感受器本身的離子通道變化，以及中樞神經的調整，使不變的刺激逐漸被忽略，讓注意力留給新的變化。","e":"進入廚房一會兒後聞不太到味道；穿上衣服很快就沒感覺。","m":"<b>習慣了就感覺不到</b>。","en":"sensory adaptation|感覺適應;habituation|習慣化"},
"freene":{"t":"游離神經末梢 free nerve endings","d":"沒有被囊包覆的感覺神經末梢，偵測痛、溫度、癢。","c":"10.2","w":"皮膚、黏膜、角膜、內臟，數量最多的感覺末梢。","f":"偵測痛覺、溫度、癢、粗略觸覺；多連到細的 Aδ 與 C 纖維。","m":"<b>裸露的末梢管痛、溫、癢</b>。","en":"free nerve endings|游離神經末梢;pain|痛覺;temperature|溫度"},
"meissner":{"t":"梅斯納小體、巴齊尼小體","d":"皮膚中兩種有「被囊」的觸覺感受器：梅斯納小體感覺輕觸，巴齊尼小體感覺深壓與振動。","c":"10.2","w":"梅斯納小體：指尖、嘴唇等無毛皮膚的真皮乳頭層（淺）。巴齊尼小體：真皮深層與皮下組織。","f":"兩者都是快適應（相位性）感受器；巴齊尼小體的層狀被囊像洋蔥，讓它對快速振動特別敏感。","m":"<b>梅斯納淺輕觸、巴齊尼深振動</b>。","en":"Meissner's corpuscle|梅斯納小體;Pacinian corpuscle|巴齊尼小體;Merkel disc|梅克爾盤;Ruffini ending|魯菲尼末梢;vibration|振動"},
"capsaicin":{"t":"辣椒素 capsaicin","d":"辣椒中的成分，活化熱感受器 TRPV1，所以吃辣會覺得「熱、痛」。","c":"10.2","f":"與 TRPV1 結合 → 打開陽離子通道 → 痛覺神經去極化，大腦解讀成「燒灼」；長時間使用使神經末梢耗竭 P 物質而變得不敏感。","e":"辣椒素藥膏用來治療帶狀疱疹後神經痛、關節痛；吃辣喝冷水沒用，喝牛奶（脂肪、酪蛋白）較能溶解辣椒素。","m":"<b>辣不是味道，是痛覺</b>。","en":"capsaicin|辣椒素;TRPV1 receptor|TRPV1 受體;chili pepper|辣椒;burning sensation|灼熱感"},
"recfield":{"t":"感受野 receptive field","d":"一個感覺神經元負責的範圍。感受野越小、越密集，感覺越精細。","c":"10.2、10.8","f":"感受野小而重疊少、感受器密度高 → 能精確定位；感受野大 → 定位粗略但敏感。","e":"指尖與嘴唇感受野小、密度高，所以點字閱讀用指尖。","m":"<b>感受野越小，越精細</b>。","en":"receptive field|感受野;sensory acuity|感覺敏銳度"},
"twopoint":{"t":"兩點辨別閾 two-point threshold","d":"皮膚上同時碰觸兩點時，能分辨出是兩點的最短距離；指尖、嘴唇最小。","c":"10.2","f":"反映感受器的密度與感受野大小：指尖約 2–3 mm，背部可達 40 mm 以上。","e":"神經學檢查用來評估觸覺敏銳度與周邊神經功能。","m":"<b>指尖最靈、背最鈍</b>。","en":"two-point discrimination threshold|兩點辨別閾;fingertips|指尖;tactile acuity|觸覺敏銳度"},
"latinh":{"t":"側抑制 lateral inhibition","d":"受刺激最強的神經元抑制周圍神經元，增強對比，使位置與邊緣更清楚。","c":"10.2、10.8","f":"中央被強烈刺激的神經元，經聯絡神經元抑制周圍較弱的神經元 → 中心與周圍的差異被放大 → 邊緣與位置更清楚。","e":"視網膜利用側抑制增強邊緣；觸覺定位、聽覺頻率辨別也用到它。","m":"<b>壓低旁邊，凸顯中間</b>。","en":"lateral inhibition|側抑制;contrast|對比;sharpen perception|使感覺更清晰"},
"referred":{"t":"轉移痛 referred pain","d":"內臟的痛被感覺成來自同一脊髓節段支配的體表，因兩者的感覺纖維會聚到同一群脊髓神經元。","e":"心肌梗塞痛到左肩與左手臂內側；膽囊痛到右肩胛；闌尾炎初期痛在肚臍周圍。","c":"10.2","f":"內臟痛覺纖維與某些體表皮膚的痛覺纖維進入脊髓同一節段、會聚到同一群上行神經元；大腦習慣把訊號解讀成來自體表。","m":"<b>心 → 左臂、膽 → 右肩</b>。","en":"referred pain|轉移痛;angina pectoris|心絞痛;left arm|左臂;visceral pain|內臟痛"},
"tastebud":{"t":"味蕾 taste buds","d":"位在舌乳頭等處、由味覺細胞（特化上皮細胞）組成的構造，約 10 天更新；接觸溶在唾液中的分子。","c":"10.3","w":"舌頭的蕈狀、輪廓、葉狀乳頭（絲狀乳頭沒有味蕾），以及軟顎、咽部；成人約 2,000–4,000 個。","f":"味覺細胞頂端的微絨毛伸出味孔，接觸溶解在唾液中的物質；訊號經顏面神經（舌前 2/3）、舌咽神經（舌後 1/3）、迷走神經傳到腦幹與島葉。","e":"缺鋅、化療、老化、口乾會使味覺下降，影響食慾與營養攝取。","m":"<b>味蕾約 10 天換新</b>；舌頭各區其實都能嚐五味。","en":"taste buds|味蕾;papillae|乳頭;gustatory cells|味覺細胞;zinc deficiency|缺鋅;dysgeusia|味覺異常"},
"umami":{"t":"鮮味 umami","d":"第五種基本味道，由麩胺酸（味精）與核苷酸（IMP、GMP）引起，代表蛋白質。","n":"日文「旨味」，1908 年池田菊苗從昆布湯中發現。","c":"10.3","f":"由 T1R1＋T1R3 受體（G 蛋白偶聯）偵測麩胺酸；核苷酸（IMP 來自肉類與柴魚、GMP 來自香菇）有加乘作用。","e":"利用鮮味（昆布、香菇、番茄、柴魚）可以在減鹽時維持美味。","m":"<b>鮮味＝麩胺酸＋核苷酸的加乘</b>。","en":"umami|鮮味;glutamate|麩胺酸;MSG=monosodium glutamate|味精;sweet|甜;sour|酸;salty|鹹;bitter|苦"},
"gustducin":{"t":"味導素 gustducin","d":"味覺細胞中專門把「甜、苦、鮮」訊號傳下去的 G 蛋白。","c":"10.3","f":"受體活化 gustducin → 磷脂酶 C → IP₃ → 細胞內 Ca²⁺↑ → 打開 TRPM5 通道 → 去極化 → 釋放 ATP 給感覺神經。鹹味（Na⁺ 經通道進入）與酸味（H⁺）則直接靠離子通道。","m":"<b>甜苦鮮走 G 蛋白、鹹酸走通道</b>。","en":"gustducin|味導素;G-protein|G 蛋白;sweet receptor|甜味受體;bitter receptor|苦味受體"},
"olfactory":{"t":"嗅覺上皮、嗅球","d":"<b>嗅覺上皮</b>在鼻腔頂部，含嗅覺受體神經元（可更新）；<b>嗅球</b>在額葉下方，接收嗅神經並直接送到嗅覺皮質與邊緣系統。","c":"10.3","w":"嗅覺上皮在鼻腔頂部約 5 cm²；嗅覺神經元的軸突穿過篩板 → 嗅球（額葉下方）→ 嗅徑 → 嗅覺皮質與邊緣系統。","f":"嗅覺是唯一不先經視丘、直接到皮質與邊緣系統（杏仁核、海馬迴）的感覺，所以氣味特別容易勾起情緒與記憶。嗅覺神經元是少數能更新的神經元（約 1–2 個月）。","e":"感冒鼻塞時食物變得「沒味道」，因為風味大多來自嗅覺。","m":"<b>嗅覺不經視丘、直通情緒與記憶</b>。","en":"olfactory epithelium|嗅覺上皮;olfactory bulb|嗅球;olfactory nerve|嗅神經;anosmia|嗅覺喪失"},
"olfrec":{"t":"嗅覺受體 olfactory receptors","d":"約 350–400 種 G 蛋白偶聯受體，每個嗅覺神經元只表現一種；不同氣味活化不同組合。","n":"2004 年 Axel 與 Buck 因發現嗅覺受體家族獲諾貝爾獎。","c":"10.3","f":"氣味分子 → 嗅覺受體 → G 蛋白（G<sub>olf</sub>）→ cAMP ↑ → 打開陽離子通道 → 去極化。每種氣味活化一組受體，大腦依組合辨識上萬種氣味。","e":"2004 年 Axel 與 Buck 因發現嗅覺受體基因家族獲諾貝爾獎。","m":"<b>受體組合像密碼</b>。","en":"olfactory receptors|嗅覺受體;odorant|氣味分子;G-protein-coupled receptor|G 蛋白偶聯受體"},
"flavor":{"t":"風味 flavor","d":"食物的整體味道＝味覺＋嗅覺（鼻後嗅覺）＋口感與溫度；大部分來自嗅覺。","c":"10.3","f":"咀嚼時食物的揮發性分子由口腔後方往上進入鼻腔（鼻後嗅覺），與味覺、口感、溫度、辣度在大腦整合成「風味」。","e":"長者嗅覺退化常覺得食物無味而吃得少、加更多鹽；可用香料、香草、增加香氣與色彩來提升風味。","m":"<b>風味＝味覺＋嗅覺＋口感</b>，嗅覺占大部分。","en":"flavor|風味;taste|味道;smell|氣味;retronasal olfaction|鼻後嗅覺"},
"vestib":{"t":"前庭器 vestibular apparatus","d":"內耳負責平衡的部分：橢圓囊、球囊（直線加速、傾斜）與三個半規管（旋轉）。","c":"10.4","w":"內耳，位於耳蝸旁的骨迷路中。","f":"<b>耳石器</b>（橢圓囊、球囊）：偵測頭部傾斜與直線加速（電梯、汽車煞車）。<b>半規管</b>：偵測頭部旋轉的角加速度。訊號經前庭神經到腦幹前庭核與小腦，維持平衡、姿勢與眼球穩定。","m":"<b>耳石管直線與傾斜、半規管管旋轉</b>。","en":"vestibular apparatus|前庭器;equilibrium|平衡;inner ear|內耳"},
"endolymph":{"t":"內淋巴、外淋巴 endolymph / perilymph","d":"內耳有兩種液體：膜迷路裡面的內淋巴（鉀很高，像細胞內液），以及外面的外淋巴（鈉高，像細胞外液）。","c":"10.4、10.5","f":"內淋巴的高 K⁺ 讓毛細胞纖毛彎曲時 K⁺ 流<b>入</b>細胞造成去極化——這是少數 K⁺ 流入使細胞興奮的例子。","e":"內淋巴過多（內淋巴水腫）是梅尼爾氏症的特徵：眩暈、耳鳴、聽力下降；常建議限鈉、少咖啡因。","m":"<b>內淋巴高鉀</b>。","en":"endolymph|內淋巴;perilymph|外淋巴;high K⁺|高鉀"},
"haircell":{"t":"毛細胞 hair cells","d":"內耳的機械感受細胞，頂端有靜纖毛；纖毛往動纖毛（最高處）方向彎曲 → K⁺ 流入去極化。","c":"10.4、10.5","f":"靜纖毛之間以尖端連結相連；往最長的動纖毛方向彎曲 → 拉開機械閘控通道 → K⁺ 流入 → 去極化 → 釋放神經傳遞物質增加；反方向彎曲 → 過極化。","e":"噪音、某些抗生素（胺基醣苷類）、老化會傷害毛細胞，人類的毛細胞不能再生。","m":"<b>往高的倒 → 興奮</b>。","en":"hair cells|毛細胞;stereocilia|靜纖毛;kinocilium|動纖毛"},
"otolith":{"t":"耳石、耳石器 otoliths","d":"內耳中像細沙一樣的碳酸鈣小晶體，讓平衡器官感覺到重力與加速。","c":"10.4","f":"耳石較重，頭傾斜或加速時會落後或滑動，拖動膠質膜 → 彎曲毛細胞纖毛。","e":"耳石脫落掉進半規管 → 良性陣發性姿勢性眩暈（翻身、抬頭時天旋地轉），可用耳石復位術治療。","n":"oto-＝耳、lith＝石。","en":"otoliths|耳石;otolith organs|耳石器;linear acceleration|直線加速度;gravity|重力"},
"utricle":{"t":"橢圓囊、球囊 utricle / saccule","d":"耳石器。<b>橢圓囊</b>偵測水平方向的加速與傾斜；<b>球囊</b>偵測垂直方向的加速。","c":"10.4","f":"橢圓囊的感覺斑大致水平，對水平加速與頭部傾斜最敏感；球囊的感覺斑大致垂直，對上下加速（電梯）最敏感。","m":"<b>橢圓囊管水平、球囊管垂直</b>。","en":"utricle|橢圓囊;saccule|球囊;macula|囊斑"},
"semicirc":{"t":"半規管 semicircular canals","d":"三個互相垂直的管道，內淋巴在頭部旋轉時推動壺腹頂，偵測旋轉加速。","c":"10.4","f":"三個管道互相垂直，分別偵測三個平面的旋轉；旋轉開始時內淋巴因慣性落後，推動壺腹頂 → 毛細胞纖毛彎曲。持續等速旋轉時內淋巴跟上，訊號就消失。","e":"轉圈停下時內淋巴繼續流動，所以停下來反而覺得還在轉。","m":"<b>三個互相垂直＝三度空間的旋轉</b>。","en":"semicircular canals|半規管;rotational acceleration|旋轉加速度;ampulla|壺腹"},
"cupula":{"t":"壺腹頂 cupula","d":"半規管壺腹中包住毛細胞纖毛的膠質帽，被內淋巴推動時使纖毛彎曲。","c":"10.4","f":"像擋在管道中的一扇膠質門；內淋巴流動時推動它，使埋在裡面的毛細胞纖毛彎曲。","m":"<b>壺腹頂＝內淋巴推動的門</b>。","en":"cupula|壺腹頂;crista ampullaris|壺腹嵴"},
"vertigo":{"t":"眩暈、眼球震顫 vertigo / nystagmus","d":"<b>眩暈</b>：天旋地轉的感覺，前庭訊號與視覺不一致時產生。<b>眼球震顫</b>：眼球不自主來回擺動。","c":"10.4","f":"前庭、視覺、本體感覺三方訊息不一致時，大腦產生旋轉感；前庭–眼反射異常造成眼球不自主來回跳動（眼球震顫）。","e":"暈車暈船是前庭訊號與視覺不一致；梅尼爾氏症、耳石脫落、前庭神經炎、腦幹或小腦病變都會引起眩暈。","m":"<b>眼睛和耳朵吵架 → 頭暈</b>。","en":"vertigo|眩暈;nystagmus|眼球震顫;motion sickness|動暈症;Ménière's disease|梅尼爾氏症"},
"tympanic":{"t":"鼓膜 tympanic membrane","d":"外耳與中耳之間的薄膜，受聲波振動。","c":"10.5","w":"外耳道的底端。","f":"聲波使鼓膜振動，振動傳給附著在上面的槌骨。","e":"中耳炎積液或鼓膜破孔會降低傳導，造成傳導性聽力損失。","m":"<b>鼓膜＝耳朵的鼓皮</b>。","en":"tympanic membrane|鼓膜;eardrum|耳膜;middle ear|中耳"},
"ossicles":{"t":"聽小骨 ossicles","d":"中耳的三塊小骨：槌骨、砧骨、鐙骨，把鼓膜振動放大約 20 倍傳到卵圓窗。","c":"10.5","f":"槌骨 → 砧骨 → 鐙骨形成槓桿；加上鼓膜面積比卵圓窗大很多，振動壓力被放大，克服由空氣進入液體時的能量損失。兩條小肌肉（鐙骨肌、鼓膜張肌）在巨大聲響時收縮保護內耳。","e":"耳硬化症使鐙骨固定，造成傳導性耳聾。","m":"<b>槌 → 砧 → 鐙</b>（鐙骨是人體最小的骨頭）。","en":"ossicles|聽小骨;malleus|鎚骨;incus|砧骨;stapes|鐙骨"},
"ovalwin":{"t":"卵圓窗、圓窗 oval / round window","d":"<b>卵圓窗</b>：鐙骨踩著的內耳入口，振動由此進入耳蝸外淋巴。<b>圓窗</b>：耳蝸另一端的膜，讓壓力波釋放回中耳。","c":"10.5","f":"鐙骨推動卵圓窗 → 耳蝸外淋巴產生壓力波 → 基底膜振動 → 壓力最後由圓窗向外鼓出釋放（液體無法壓縮，需要另一個出口）。","m":"<b>卵圓窗進、圓窗出</b>。","en":"oval window|卵圓窗;round window|圓窗;cochlea|耳蝸"},
"eust":{"t":"耳咽管 auditory (Eustachian) tube","d":"連接中耳與咽部的管道，吞嚥或打哈欠時打開，平衡中耳與外界的氣壓。","c":"10.5","f":"平時關閉，吞嚥、打哈欠時打開，讓中耳氣壓與外界相同，鼓膜才能自由振動；也讓中耳分泌物流向咽部。","e":"飛機下降時耳朵悶痛，吞口水或打哈欠可緩解；兒童的耳咽管短而水平，咽部感染容易蔓延成中耳炎。","n":"又稱歐氏管，以 16 世紀義大利解剖學家 Eustachi 命名。","en":"auditory tube|耳咽管;Eustachian tube|歐氏管;pressure equalization|平衡壓力;otitis media|中耳炎"},
"cochlea":{"t":"耳蝸 cochlea","d":"內耳盤繞約 2¾ 圈的聽覺器官，內有基底膜與柯蒂氏器。","n":"拉丁文「蝸牛殼」。","c":"10.5","f":"內部分成三條管道：前庭階、蝸管（中階，含內淋巴與柯蒂氏器）、鼓階。聲波使基底膜振動，柯蒂氏器的毛細胞把振動轉成神經訊號，經耳蝸神經 → 腦幹 → 視丘內側膝狀核 → 顳葉聽覺皮質。","m":"<b>耳蝸＝把聲音變成電的蝸牛殼</b>。","en":"cochlea|耳蝸;scala vestibuli|前庭階;scala tympani|鼓室階;cochlear duct|耳蝸管"},
"basilar":{"t":"基底膜 basilar membrane（耳蝸）","d":"耳蝸蝸管底部的膜，上面坐著柯蒂氏器；底部窄硬對高音、頂部寬軟對低音（位置理論）。","c":"10.5","f":"不同頻率的聲音使基底膜不同位置振動最大（位置編碼）：靠近卵圓窗的底部窄而硬 → 高音；耳蝸頂部寬而軟 → 低音。","e":"老年性聽力損失常從高頻開始，因為底部毛細胞最先受損。","m":"<b>底高頂低</b>。","en":"basilar membrane|基底膜;pitch|音高;frequency|頻率;tonotopic|音頻定位"},
"corti":{"t":"柯蒂氏器 organ of Corti（spiral organ）","d":"耳蝸基底膜上的聽覺感受器，由內毛細胞（傳訊）、外毛細胞（放大）與支持細胞組成，纖毛抵住上方的覆膜。","c":"10.5","w":"耳蝸蝸管內、基底膜之上，上方覆蓋著蓋膜。","f":"基底膜振動 → 毛細胞纖毛與蓋膜相對移動而彎曲 → 內毛細胞（約 3,500 個）把訊號傳給聽神經；外毛細胞會伸縮放大振動，提高敏感度與頻率辨別。","n":"以 19 世紀義大利解剖學家 Alfonso Corti 命名。","m":"<b>內毛細胞傳訊、外毛細胞放大</b>。","en":"organ of Corti|柯蒂氏器;spiral organ|螺旋器;tectorial membrane|蓋膜;inner hair cells|內毛細胞"},
"deaf":{"t":"傳導性、感音神經性耳聾","d":"聽力損失分兩大類：聲音「傳不進去」叫傳導性，內耳或聽神經「收不到」叫感音神經性。","c":"10.5","f":"<b>傳導性</b>：外耳道、鼓膜、聽小骨的問題，骨傳導仍正常。<b>感音神經性</b>：毛細胞或聽神經受損（噪音、老化、耳毒性藥物、遺傳），重度者可用人工電子耳。","m":"<b>傳導性：路塞住；感音神經性：收音器壞了</b>。","en":"conduction deafness|傳導性耳聾;sensorineural deafness|感音神經性耳聾;cochlear implant|人工電子耳;hearing aid|助聽器"},
"cornea":{"t":"角膜 cornea","d":"眼球最前方透明、無血管的部分，提供約 2/3 的折射力（固定）。","c":"10.6","f":"表面弧度固定、透明，提供大部分的折射力；沒有血管，養分來自房水與淚液，但有大量神經末梢，非常敏感。","e":"近視雷射手術就是削薄角膜改變曲度；維生素 A 嚴重缺乏 → 角膜乾燥、軟化甚至穿孔。","m":"<b>角膜：最主要的固定鏡頭</b>。","en":"cornea|角膜;transparent|透明;refraction|折射;xerophthalmia|乾眼症;keratomalacia|角膜軟化症"},
"lens":{"t":"水晶體 lens","d":"虹膜後方的雙凸透明構造，提供約 1/3 的折射力，可改變形狀調節焦距。變混濁＝白內障。","c":"10.6","f":"由排列整齊、不含胞器的透明細胞組成，富含晶體蛋白；靠睫狀肌與懸韌帶改變弧度，負責「調焦」。","e":"老化、糖尿病（山梨醇堆積）、紫外線、抽菸使晶體蛋白變性聚集 → 白內障。","m":"<b>水晶體：可變焦的鏡頭</b>。","en":"lens|水晶體;crystallins|晶體蛋白;accommodation|調節作用"},
"iris":{"t":"虹膜、瞳孔 iris / pupil","d":"<b>虹膜</b>是眼睛有顏色的部分，含環狀肌（副交感，縮小瞳孔）與輻射狀肌（交感，放大瞳孔）；中間的孔是<b>瞳孔</b>。","c":"10.6；第 9 章","f":"<b>瞳孔括約肌</b>（環狀，副交感，ACh）收縮 → 瞳孔縮小；<b>瞳孔放大肌</b>（輻射狀，交感，α₁）收縮 → 瞳孔放大。強光時瞳孔反射縮小，保護視網膜並增加景深。","e":"有機磷中毒、鴉片類 → 瞳孔縮小；阿托平、驚嚇 → 瞳孔放大。","m":"<b>副交感縮、交感放</b>。","en":"iris|虹膜;pupil|瞳孔;pupillary reflex|瞳孔反射;constriction|縮小;dilation|放大"},
"ciliary":{"t":"睫狀體、懸韌帶 ciliary body / suspensory ligament","d":"<b>睫狀體</b>含睫狀肌並分泌房水；<b>懸韌帶</b>連接睫狀體與水晶體。看近時睫狀肌收縮、懸韌帶放鬆、水晶體變圓。","c":"10.6","f":"睫狀肌收縮 → 睫狀體往前內縮 → 懸韌帶放鬆 → 水晶體因自身彈性變圓 → 看近；睫狀肌放鬆 → 懸韌帶拉緊 → 水晶體變扁 → 看遠。睫狀體上皮也分泌房水。","m":"<b>看近：肌肉縮、韌帶鬆、水晶體圓</b>。","en":"ciliary body|睫狀體;ciliary muscle|睫狀肌;suspensory ligament|懸韌帶;zonular fibers|小帶纖維"},
"aqueous":{"t":"房水、玻璃體 aqueous humor / vitreous body","d":"<b>房水</b>：角膜與水晶體之間的液體，由睫狀體分泌、經許萊姆氏管排出；排出受阻 → 青光眼。<b>玻璃體</b>：水晶體後的膠狀物。","c":"10.6","f":"房水供應角膜與水晶體養分並維持眼壓；由睫狀體持續分泌 → 經瞳孔到前房 → 經前房角的許萊姆氏管回到靜脈。玻璃體是水晶體後方的膠狀物，撐住眼球形狀。","e":"房水排出受阻 → 眼壓升高 → 青光眼。","m":"<b>房水不斷流動、玻璃體固定不換</b>。","en":"aqueous humor|房水;vitreous body|玻璃體;canal of Schlemm|許萊姆氏管;intraocular pressure|眼內壓"},
"accom":{"t":"調節作用 accommodation","d":"水晶體改變形狀以對焦遠近：看近時睫狀肌收縮 → 懸韌帶鬆 → 水晶體變圓。","c":"10.6","f":"看近物時三件事同時發生（近反射）：水晶體變圓、瞳孔縮小、兩眼內聚；由副交感神經控制。","e":"長時間看近（手機、書本）睫狀肌持續收縮，容易眼睛疲勞；看遠方可以讓它放鬆。","m":"<b>看近：變圓、縮瞳、鬥雞眼</b>。","en":"accommodation|調節作用;near vision|近距離視力;ciliary muscle contraction|睫狀肌收縮"},
"refraction":{"t":"折射 refraction","d":"光線進入密度不同的介質時方向彎折；眼睛靠角膜與水晶體折射，在視網膜上成像。","c":"10.6","f":"光從空氣進入角膜時彎折最多（兩者密度差最大），水晶體再微調；正常眼睛讓遠處的光剛好聚焦在視網膜上，成像是上下左右顛倒的，由大腦轉正。","m":"<b>角膜大轉彎、水晶體微調</b>。","en":"refraction|折射;focal point|焦點;convex lens|凸透鏡;diopter|屈光度"},
"myopia":{"t":"近視、遠視 myopia / hyperopia","d":"<b>近視</b>：眼球太長或折射太強，成像在視網膜前，看遠模糊，用凹透鏡。<b>遠視</b>：眼球太短，成像在後，用凸透鏡。","c":"10.6","f":"近視：眼軸太長或折射太強 → 遠方影像聚焦在視網膜前方 → 凹透鏡（發散）矯正。遠視：眼軸太短或折射太弱 → 聚焦在視網膜後方 → 凸透鏡（會聚）矯正。","e":"台灣學童近視盛行率高，戶外活動與減少長時間近距離用眼有助於預防。","m":"<b>近視凹、遠視凸</b>。","en":"myopia|近視;hyperopia|遠視;nearsightedness|近視;farsightedness|遠視;concave lens|凹透鏡;convex lens|凸透鏡"},
"presby":{"t":"老花眼 presbyopia","d":"年紀增長水晶體失去彈性，看近時無法變圓，近點變遠；用凸透鏡（老花眼鏡）。","n":"presby-＝老、-opia＝眼睛（視力）。","c":"10.6","f":"水晶體隨年齡變硬、睫狀肌力量下降 → 看近時無法變圓 → 近點越來越遠，通常 40 多歲開始。","m":"<b>老花＝水晶體變硬</b>，和近視可以同時存在。","en":"presbyopia|老花眼;loss of lens elasticity|水晶體失去彈性;aging|老化"},
"astig":{"t":"散光 astigmatism","d":"角膜或水晶體不同方向的曲度不同，使某些方向的線條模糊；用柱狀透鏡矯正。","c":"10.6","f":"正常角膜像籃球各方向弧度相同；散光的角膜像橄欖球，不同方向的焦點落在不同位置，所以某些方向的線看得清楚、某些模糊。","n":"a-＝沒有、stigma＝點：光線無法聚成一個點。","m":"<b>籃球形正常、橄欖球形散光</b>。","en":"astigmatism|散光;irregular curvature|曲度不規則;cylindrical lens|圓柱透鏡"},
"glaucoma":{"t":"青光眼 glaucoma","d":"房水排出受阻使眼壓升高，壓迫並損傷視神經，造成視野缺損甚至失明。","c":"10.6","f":"多數是房水排出慢、眼壓升高 → 長期壓迫視神經盤 → 神經節細胞的軸突死亡 → 視野從周邊開始缺損，早期常無症狀，損傷無法恢復。","e":"40 歲以上、有家族史、高度近視者應定期量眼壓與檢查視神經。","m":"<b>青光眼＝偷走視力的小偷</b>（先缺周邊）。","en":"glaucoma|青光眼;intraocular pressure|眼內壓;optic nerve damage|視神經損傷"},
"cataract":{"t":"白內障 cataract","d":"水晶體變混濁，與老化、糖尿病、紫外線有關；以手術更換人工水晶體。","c":"10.6","f":"晶體蛋白氧化、醣化、聚集 → 水晶體混濁 → 視力模糊、畏光、顏色變淡。","e":"糖尿病高血糖使水晶體中山梨醇堆積而加速白內障；富含抗氧化物（維生素 C、E、葉黃素）的飲食可能有幫助。","m":"<b>白內障＝鏡頭起霧</b>。","en":"cataract|白內障;lens opacity|水晶體混濁;diabetes|糖尿病;sorbitol|山梨醇;lutein|葉黃素"},
"retina":{"t":"視網膜 retina","d":"眼球最內層的神經組織，含感光細胞（桿、錐）、雙極細胞、神經節細胞，把光轉成神經訊號。","c":"10.7","w":"眼球最內層，貼在脈絡膜（富含血管）上。","f":"光線要先穿過神經節細胞、雙極細胞才到達最外層的感光細胞（倒置的構造）；感光細胞 → 雙極細胞 → 神經節細胞（軸突組成視神經）。色素上皮層吸收多餘光線、回收視網醛、吞噬感光細胞脫落的外節。","e":"糖尿病視網膜病變是成人失明的重要原因；控制血糖與血壓可延緩。","m":"<b>感光 → 雙極 → 神經節 → 視神經</b>。","en":"retina|視網膜;photoreceptor layer|光感受器層;bipolar cells|雙極細胞;ganglion cells|神經節細胞;diabetic retinopathy|糖尿病視網膜病變"},
"rods":{"t":"桿細胞、錐細胞 rods / cones","d":"視網膜上兩種感光細胞：桿細胞負責暗處、錐細胞負責顏色與細節。","c":"10.7","f":"桿細胞：數量多、非常敏感、許多會聚到一個神經節細胞（敏感但模糊），只有一種色素（視紫質），只看黑白。錐細胞：集中在中央小窩、一對一連接（清晰），三種色素看顏色，需要較亮的光。","e":"夜晚看星星時，用眼角（周邊視網膜）看反而看得到暗的星。","m":"<b>桿：暗、黑白、周邊；錐：亮、彩色、中央</b>。","en":"rods|桿細胞;cones|錐細胞;scotopic vision|暗視覺;photopic vision|明視覺;color vision|色覺"},
"rhodopsin":{"t":"視紫質 rhodopsin","d":"桿細胞的感光色素＝視蛋白＋11-順式視網醛（來自維生素 A）；光使其漂白並啟動視覺訊號。","c":"10.7","f":"光使 11-順式視網醛變成全反式 → 視紫質活化 → 轉導素 → 磷酸二酯酶分解 cGMP → 鈉通道關閉 → 桿細胞<b>過極化</b> → 減少釋放麩胺酸 → 訊號傳出。之後全反式視網醛與視蛋白分離（漂白），再由色素上皮細胞轉回 11-順式重新組合。","m":"<b>視紫質＝視蛋白＋11-順式視網醛</b>；照光後漂白。","en":"rhodopsin|視紫質;visual purple|視紫;opsin|視蛋白;11-cis-retinal|11-順-視網醛;bleaching|漂白"},
"retinal":{"t":"視網醛 retinal","d":"維生素 A 的醛類形式，是感光色素中真正「吸收光」的部分。","c":"10.7；營養學","f":"視網醇（運送型）在眼睛氧化成視網醛；11-順式視網醛吸收光子後變成全反式，引起視蛋白形狀改變，視覺訊號從這裡開始。","m":"<b>醛看東西</b>（醇運送、酸管基因）。","en":"retinal|視網醛;vitamin A|維生素 A;retinol|視網醇;all-trans-retinal|全反式視網醛"},
"transducin":{"t":"轉導素 transducin","d":"視紫質活化的 G 蛋白，進而活化磷酸二酯酶分解 cGMP，使鈉通道關閉。","c":"10.7","f":"活化的視紫質讓轉導素換上 GTP → 活化 cGMP 磷酸二酯酶 → cGMP 下降 → cGMP 閘控鈉通道關閉。一個視紫質可活化數百個轉導素，訊號被大幅放大，所以桿細胞能偵測單一光子。","m":"<b>光 → 視紫質 → 轉導素 → cGMP↓ → 鈉通道關</b>。","en":"transducin|轉導素;cGMP phosphodiesterase|cGMP 磷酸二酯酶;dark current|暗電流"},
"darkadapt":{"t":"暗適應、光適應 dark / light adaptation","d":"<b>暗適應</b>：進入暗處後視紫質逐漸再生，敏感度增加約 10 萬倍以上（20–30 分鐘）。<b>光適應</b>：進入亮處後視紫質漂白，敏感度下降（較快）。","c":"10.7","f":"暗適應：視紫質逐漸再生，加上瞳孔放大、神經調整，約 20–30 分鐘大致完成。光適應：視紫質大量漂白、錐細胞接手，約數分鐘內完成。","e":"從大太陽下走進電影院，一開始看不見，慢慢才看得清楚；維生素 A 不足時暗適應變慢。","m":"<b>暗適應慢、光適應快</b>。","en":"dark adaptation|暗適應;light adaptation|光適應;rhodopsin regeneration|視紫質再生"},
"nightblind":{"t":"夜盲症 night blindness","d":"維生素 A 缺乏使視紫質再生不足，在暗處或黃昏看不清楚；是維生素 A 缺乏最早的症狀之一。","c":"10.7；營養學","f":"視網醛不足 → 視紫質再生不夠 → 桿細胞在暗處失去敏感度；錐細胞在亮處仍可工作，所以白天看似正常。","e":"補充維生素 A 後可改善；嚴重缺乏進一步出現乾眼症、畢托氏斑、角膜軟化而失明。","m":"<b>夜盲是維生素 A 缺乏最早的徵兆</b>。","en":"night blindness|夜盲症;nyctalopia|夜盲;vitamin A deficiency|維生素 A 缺乏;Bitot's spots|畢托氏斑"},
"fovea":{"t":"中央小窩、黃斑部 fovea centralis / macula lutea","d":"<b>黃斑部</b>是視網膜中央的黃色區域（含葉黃素、玉米黃素），其中心的<b>中央小窩</b>只有錐細胞，是視覺最清晰處。","c":"10.7","w":"視網膜正中央、正對視軸的位置；黃斑部約 5 mm，中央小窩在它的中心。","f":"中央小窩只有錐細胞、密度最高、而且上層的神經細胞被推開，光線直接照到錐細胞 → 視力最清晰。看東西時眼睛會把影像對準這裡。","e":"老年性黃斑部病變使中央視力喪失；葉黃素與玉米黃素集中在黃斑部，能過濾藍光、抗氧化。","m":"<b>中央小窩＝最清楚的焦點</b>。","en":"fovea centralis|中央小窩;macula lutea|黃斑部;visual acuity|視覺敏銳度;age-related macular degeneration|老年性黃斑部病變;lutein|葉黃素;zeaxanthin|玉米黃素"},
"trichrom":{"t":"三色理論 trichromatic theory","d":"三種錐細胞分別對藍、綠、紅光最敏感，腦依三者被活化的比例判斷顏色。","c":"10.7","f":"S（短波，藍）、M（中波，綠）、L（長波，紅）三種錐細胞的吸收範圍重疊；大腦依三者的相對活化比例調配出所有顏色，就像螢幕的 RGB。","m":"<b>三原色 RGB</b>。","en":"trichromatic theory|三色理論;blue cones|藍錐;green cones|綠錐;red cones|紅錐"},
"colorblind":{"t":"色盲 color blindness","d":"缺少某種錐細胞或光視素異常；最常見的紅綠色盲為 X 性聯隱性遺傳，男性較多。","c":"10.7","f":"紅與綠光視素的基因位於 X 染色體 → X 性聯隱性遺傳：男性只有一條 X，一個缺陷基因就會表現；女性需要兩條都有缺陷。","e":"台灣男性紅綠色盲約 5%、女性不到 1%。","m":"<b>紅綠色盲：X 性聯、男多女少</b>。","en":"color blindness|色盲;red-green color blindness|紅綠色盲;X-linked recessive|性聯隱性"},
"blindspot":{"t":"盲點 blind spot（視神經盤）","d":"視神經離開眼球處，沒有感光細胞，所以看不到落在這裡的影像。","c":"10.7","w":"視神經盤，位於中央小窩鼻側約 15 度處，也是視網膜血管進出的地方。","f":"這裡沒有桿細胞與錐細胞；平常兩眼視野互補，加上大腦「補圖」，所以不會察覺。","e":"眼底鏡檢查視神經盤可看出青光眼、顱內壓升高（視乳頭水腫）。","m":"<b>神經出口＝沒有感光細胞</b>。","en":"blind spot|盲點;optic disc|視神經盤;no photoreceptors|沒有光感受器"},
"chiasma":{"t":"視交叉 optic chiasma","d":"兩條視神經在腦下方的交會處，兩眼鼻側視網膜的纖維在此交叉到對側，使左視野送到右腦。","c":"10.8；第 11 章","f":"兩眼<b>鼻側</b>視網膜（看外側視野）的纖維交叉，<b>顳側</b>的不交叉 → 左視野的訊息全部送到右腦、右視野送到左腦。","e":"腦下垂體腫瘤壓迫視交叉 → 兩眼外側視野缺損（雙顳側偏盲）。","m":"<b>鼻側交叉、顳側不交叉</b>。","en":"optic chiasma|視交叉;optic tract|視徑;crossing of nasal fibers|鼻側纖維交叉"},
"lgn":{"t":"外側膝狀核 lateral geniculate nucleus","d":"視丘中負責轉送視覺訊號到枕葉視覺皮質的神經核。","c":"10.8","f":"視神經纖維在視丘的外側膝狀核換神經元，再經視放射到枕葉；外側膝狀核也接收皮質回饋，調整傳送的訊息。","m":"<b>看見的轉運站：外側膝狀核；聽見的：內側膝狀核</b>。","en":"LGN=lateral geniculate nucleus|外側膝狀核;thalamus|視丘;visual relay|視覺中繼"},
"visualcx":{"t":"視覺皮質 visual cortex","d":"枕葉的視覺處理區；之後分腹側（往顳葉：是什麼）與背側（往頂葉：在哪裡、怎麼動）兩條路徑。","c":"10.8","w":"<b>枕葉</b>，初級視覺皮質在距狀溝兩側。","f":"初級視覺皮質處理線條方向、邊緣、運動；再分成腹側路徑（往顳葉，辨認物體與臉孔：是什麼）與背側路徑（往頂葉，位置與動作：在哪裡）。","e":"枕葉中風 → 對側視野缺損；顳葉梭狀迴受損 → 認不出熟人的臉（臉盲）。","m":"<b>腹側問「是什麼」、背側問「在哪裡」</b>。","en":"visual cortex|視覺皮質;occipital lobe|枕葉;striate cortex|紋狀皮質"}});
Object.assign(GL_ALIAS,{"化學感受器":"chemorec","光感受器":"photorec","機械感受器":"mechanorec","痛覺感受器":"nocirec","傷害感受器":"nocirec","溫度感受器":"thermorec","特定神經能量定律":"lsne","適當刺激":"adequate","轉導":"transduc","發生器電位":"genpot","感受器電位":"genpot","緊張性":"tonicrec","相位性":"tonicrec","適應":"adaptation","游離神經末梢":"freene","梅斯納小體":"meissner","巴齊尼小體":"meissner","辣椒素":"capsaicin","感受野":"recfield","兩點辨別":"twopoint","兩點辨別閾":"twopoint","側抑制":"latinh","轉移痛":"referred","味蕾":"tastebud","鮮味":"umami","味導素":"gustducin","嗅覺上皮":"olfactory","嗅球":"olfactory","嗅覺受體":"olfrec","風味":"flavor","前庭器":"vestib","內淋巴":"endolymph","外淋巴":"endolymph","毛細胞":"haircell","耳石":"otolith","橢圓囊":"utricle","球囊":"utricle","半規管":"semicirc","壺腹頂":"cupula","眩暈":"vertigo","眼球震顫":"vertigo","鼓膜":"tympanic","聽小骨":"ossicles","卵圓窗":"ovalwin","圓窗":"ovalwin","耳咽管":"eust","耳蝸":"cochlea","柯蒂氏器":"corti","傳導性耳聾":"deaf","感音神經性":"deaf","角膜":"cornea","水晶體":"lens","虹膜":"iris","瞳孔":"iris","睫狀肌":"ciliary","睫狀體":"ciliary","懸韌帶":"ciliary","房水":"aqueous","玻璃體":"aqueous","調節作用":"accom","折射":"refraction","近視":"myopia","遠視":"myopia","老花":"presby","老花眼":"presby","散光":"astig","青光眼":"glaucoma","白內障":"cataract","視網膜":"retina","桿細胞":"rods","錐細胞":"rods","視紫質":"rhodopsin","視網醛":"retinal","轉導素":"transducin","暗適應":"darkadapt","光適應":"darkadapt","夜盲症":"nightblind","中央小窩":"fovea","黃斑部":"fovea","三色理論":"trichrom","色盲":"colorblind","盲點":"blindspot","視交叉":"chiasma","外側膝狀核":"lgn","視覺皮質":"visualcx"});

/* ---- end ch10 ---- */
