Object.assign(GL,{"co":{"t":"心輸出量 cardiac output","d":"每分鐘一個心室打出的血量＝心率 × 心搏量；靜止約 5 L/分，劇烈運動可達 20–35 L/分。","c":"14.1","f":"心輸出量＝心率 × 心搏量（約 70 次 × 70 mL ≈ 5 L/分），等於全身血液每分鐘循環一次；運動時心率與心搏量都增加，訓練有素的運動員可達 35 L/分。血壓＝心輸出量 × 總周邊阻力。","e":"心衰竭、嚴重脫水、大量失血時心輸出量下降 → 組織灌流不足。","m":"<b>CO＝HR × SV；BP＝CO × TPR</b>。","en":"cardiac output|心輸出量;heart rate times stroke volume|心率乘心搏量;liters per minute|公升／分鐘"},
"hr":{"t":"心率 heart rate","d":"每分鐘心跳次數；竇房結本身約 100，靜止時因迷走神經抑制約 70；交感與腎上腺素使其加快。","c":"14.1","f":"交感神經（β₁）與腎上腺素加快節律點電位的斜率 → 心率↑；副交感（迷走神經 ACh）減慢 → 心率↓。其他影響：體溫、甲狀腺激素、血鉀、年齡、體能狀態。","e":"最大心率約為 220－年齡；耐力運動員靜止心率可低到 40–60 次。","m":"<b>交感加速、迷走減速</b>。","en":"heart rate|心率;beats per minute|每分鐘心跳次數;chronotropic|變時性"},
"preload":{"t":"前負荷、後負荷 preload / afterload","d":"前負荷是「心臟打出去之前，心室被血撐得多滿」；後負荷是「心臟要對抗多大的壓力才能打出去」。","c":"14.1","f":"前負荷↑（回流多）→ 心搏量↑（法蘭克–史達林）。後負荷↑（高血壓、主動脈瓣狹窄）→ 心搏量↓、心臟耗氧↑、久了左心室肥厚。","e":"利尿劑減少前負荷（減輕淤血）；降血壓藥減少後負荷。","m":"<b>前負荷＝裝多少、後負荷＝推多重</b>。","en":"preload|前負荷;afterload|後負荷;end-diastolic volume|心舒期末容積;aortic pressure|主動脈壓"},
"contractility":{"t":"收縮力 contractility","d":"在相同心舒期末容積下心肌收縮的力量；交感神經與腎上腺素經 β₁、cAMP 使 Ca²⁺ 增加而增強（正變力作用）。","c":"14.1","f":"由心肌細胞內 Ca²⁺ 的量決定：交感神經 → β₁ → cAMP → 增加 L 型鈣通道 Ca²⁺ 流入與肌漿網釋放 → 更多橫橋 → 同樣的 EDV 打出更多血（ESV 下降）。","e":"毛地黃（digoxin）抑制鈉鉀幫浦 → 間接增加細胞內 Ca²⁺ → 增強收縮力；心肌缺血、酸中毒、低血鈣使收縮力下降。","m":"<b>收縮力看 Ca²⁺</b>。","en":"contractility|收縮力;positive inotropic effect|正變力作用;sympathetic stimulation|交感刺激"},
"inotropic":{"t":"變力作用、變時作用","d":"「變力」是改變心臟收縮的力氣，「變時」是改變心臟跳的快慢。","c":"14.1","f":"正變力：交感神經、腎上腺素、毛地黃、Ca²⁺。正變時：交感神經、腎上腺素、甲狀腺激素。負變力與負變時：副交感（主要影響心率）、β 阻斷劑、鈣通道阻斷劑。","n":"ino-＝纖維（力量）、chrono-＝時間。","m":"<b>ino 管力氣、chrono 管快慢</b>。","en":"inotropic effect|變力作用;chronotropic effect|變時作用;dromotropic effect|變傳導作用;digitalis|毛地黃"},
"frankstarling":{"t":"法蘭克—史達林定律 Frank-Starling law","d":"回流越多（EDV↑），心肌被拉長越多，收縮越強、心搏量越大；心臟的內在調節，使左右心室輸出相等。","e":"橡皮筋拉得越開，彈回越有力（在一定範圍內）。","c":"14.1","f":"心肌在正常範圍內被拉得越長，粗細肌絲重疊越適當、對 Ca²⁺ 越敏感 → 收縮越強。這讓左右心室自動維持相同的輸出量：回來多少就打出去多少。","m":"<b>進多少、出多少</b>。","en":"Frank-Starling law of the heart|心臟的法蘭克-史達林定律;stretch|伸展;intrinsic regulation|內在調節"},
"tpr":{"t":"總周邊阻力 total peripheral resistance","d":"全身血管對血流阻力的總和，主要由小動脈口徑決定；平均動脈壓 ≈ 心輸出量 × 總周邊阻力。","c":"14.1、14.3","f":"阻力與血管半徑的四次方成反比，所以小動脈的收縮與放鬆最能改變總周邊阻力。交感神經（α₁）、血管收縮素 II、ADH 使阻力增加；一氧化氮、局部代謝物使阻力下降。","e":"長期高血壓多半是總周邊阻力增加。","m":"<b>BP＝CO × TPR</b>。","en":"TPR=total peripheral resistance|總周邊阻力;systemic vascular resistance|全身血管阻力;arteriole radius|小動脈半徑"},
"venreturn":{"t":"靜脈回流 venous return","d":"每分鐘回到右心房的血量，決定心舒期末容積；靠靜脈收縮、骨骼肌幫浦、呼吸幫浦與血容積。","c":"14.1","f":"回到右心房的血量決定前負荷：靜脈收縮（交感）、骨骼肌幫浦、呼吸幫浦、總血量增加 → 回流↑；出血、脫水、久站不動、胸內壓上升 → 回流↓。長期來說心輸出量等於靜脈回流量。","m":"<b>心臟只能打出回來的血</b>。","en":"venous return|靜脈回流;venous pressure|靜脈壓;blood volume|血量"},
"starlingf":{"t":"史達林力 Starling forces","d":"決定微血管與組織間液體流動的力量：微血管靜水壓（推出）與血漿膠體滲透壓（拉回）。動脈端淨濾出、靜脈端淨吸回。","c":"14.2","f":"<b>微血管動脈端</b>：靜水壓（約 35 mmHg）＞膠體滲透壓（約 25）→ 液體濾出到組織。<b>靜脈端</b>：靜水壓降到約 15，膠體滲透壓仍約 25 → 液體被拉回血管。濾出略多於回收，多餘的約 10% 由淋巴帶回。","e":"任何一個力失衡就會水腫：心衰竭（靜水壓↑）、低白蛋白（膠體滲透壓↓）。","m":"<b>靜水壓推出、膠體滲透壓拉回</b>。","en":"Starling forces|史達林力;filtration|過濾;reabsorption|再吸收;net filtration pressure|淨過濾壓"},
"oncotic":{"t":"膠體滲透壓 colloid osmotic pressure","d":"留在血管內的蛋白質（主要是白蛋白）產生的滲透壓，約 25 mmHg，把水拉回血管。","c":"14.2","f":"微血管壁擋住大分子蛋白質，所以血漿蛋白在血管內產生吸水的力量；組織液蛋白質很少，對抗力量小。","e":"白蛋白低於約 2.5 g/dL 時常出現水腫；肝硬化腹水病人有時輸注白蛋白。","n":"onco-＝團塊（指大分子）。","m":"<b>膠體滲透壓＝白蛋白把水拉住</b>。","en":"colloid osmotic pressure|膠體滲透壓;oncotic pressure|膠體滲透壓;plasma proteins|血漿蛋白;albumin|白蛋白"},
"hydrostatic":{"t":"靜水壓 hydrostatic pressure","d":"液體本身對管壁的壓力；在微血管就是血壓，把液體推出血管。","c":"14.2","f":"在微血管動脈端最高、往靜脈端逐漸下降；站立時下肢微血管的靜水壓因重力而更高。","e":"久站後腳踝水腫；心衰竭使靜脈壓升高 → 微血管靜水壓升高 → 水腫。","m":"<b>靜水壓＝往外推的力</b>。","en":"hydrostatic pressure|靜水壓;capillary blood pressure|微血管血壓;arterial end|動脈端;venous end|靜脈端"},
"vasopressin":{"t":"血管加壓素 vasopressin","d":"ADH 的另一個名字：高濃度時使血管收縮，故名。","c":"14.2、14.3","f":"同一個激素有兩種作用：在腎臟（V₂ 受體，cAMP）插入水通道回收水；在血管（V₁ 受體，IP₃）使小動脈收縮。大量失血、低血壓時分泌量很高，兩種作用一起幫忙維持血壓。","e":"敗血性休克時會用血管加壓素升壓。","m":"<b>ADH＝抗利尿＋升壓</b>。","en":"vasopressin|血管加壓素;ADH=antidiuretic hormone|抗利尿激素;water retention|保水;vasoconstriction|血管收縮"},
"renin":{"t":"腎素 renin","d":"腎臟近腎絲球細胞在血壓或血量下降、交感興奮時分泌的酵素，把血管收縮素原切成血管收縮素 I。","c":"14.2；第 17 章","w":"腎臟入球小動脈壁上的<b>近腎絲球細胞</b>。","f":"三個刺激：①入球小動脈血壓下降（壓力感受）；②緻密斑偵測到流到遠端小管的 NaCl 減少；③交感神經（β₁）。腎素把肝臟製造的血管收縮素原切成血管收縮素 I——這是 RAAS 的速率限制步驟。","m":"<b>腎素是酵素，不是激素作用者</b>。","en":"renin|腎素;angiotensinogen|血管收縮素原;rate-limiting step|速率限制步驟"},
"jgcell":{"t":"近腎絲球細胞 juxtaglomerular cells","d":"腎臟小動脈壁上會「量血壓」並分泌腎素的細胞。","c":"14.2；第 17 章","f":"與遠曲小管的緻密斑合組成近腎絲球器：近腎絲球細胞感受入球小動脈的壓力，緻密斑感受小管液中的鈉氯，共同決定腎素分泌。","m":"<b>近腎絲球器＝腎臟的血壓計</b>。","en":"juxtaglomerular cells|近腎絲球細胞;granular cells|顆粒細胞;afferent arteriole|入球小動脈"},
"angiotensin":{"t":"血管收縮素 angiotensin","d":"血管收縮素原（肝）→ I（腎素）→ II（ACE）。<b>血管收縮素 II</b>：收縮小動脈、刺激醛固酮、口渴與 ADH。","c":"14.2","f":"血管收縮素 II 的作用：①強力收縮小動脈（血壓↑）；②刺激腎上腺皮質分泌<b>醛固酮</b>（保鈉保水）；③刺激<b>口渴</b>與 ADH 分泌；④增加交感神經活性；⑤使出球小動脈收縮維持腎絲球過濾率；⑥長期促進心臟與血管重塑。","m":"<b>血管收縮素 II：縮、留鈉、口渴、ADH</b>。","en":"angiotensin I|血管收縮素 I;angiotensin II|血管收縮素 II;vasoconstrictor|血管收縮劑;thirst|口渴"},
"ace":{"t":"血管收縮素轉化酶 ACE","d":"主要在肺微血管內皮，把血管收縮素 I 轉成 II，也分解緩激肽；ACE 抑制劑（-pril）用來降血壓。","c":"14.2、14.7","w":"主要在<b>肺微血管</b>的內皮細胞表面（全身血管內皮也有）。","f":"把血管收縮素 I 轉成有活性的 II；同時分解緩激肽（一種血管擴張物質）。","e":"ACE 抑制劑使緩激肽累積 → 部分病人出現乾咳。","m":"<b>ACE：造升壓的、拆降壓的</b>。","en":"ACE=angiotensin-converting enzyme|血管收縮素轉化酶;lungs|肺;bradykinin breakdown|分解緩激肽"},
"raas":{"t":"腎素—血管收縮素—醛固酮系統 RAAS","d":"血壓↓ → 腎素 → 血管收縮素 II → 血管收縮＋醛固酮（保鈉保水）＋口渴與 ADH → 血壓回升。","c":"14.2","f":"血壓或血量↓ → 腎素 → 血管收縮素原 → 血管收縮素 I →（肺 ACE）→ 血管收縮素 II → 血管收縮、醛固酮（腎臟留鈉、排鉀）、口渴與 ADH（留水）→ 血量與血壓回升。是血壓的<b>中長期</b>調節。","e":"高鈉飲食時 RAAS 受抑制；限鈉時 RAAS 活化——所以單靠限鈉的降壓效果因人而異。","m":"<b>肝 → 腎 → 肺 → 腎上腺</b>（血管收縮素原、腎素、ACE、醛固酮）。","en":"RAAS=renin-angiotensin-aldosterone system|腎素-血管收縮素-醛固酮系統;blood volume|血量;blood pressure|血壓;sodium retention|保鈉"},
"arb":{"t":"ACE 抑制劑、ARB","d":"降血壓藥：<b>ACE 抑制劑</b>（-pril）阻止血管收縮素 II 生成；<b>ARB</b>（-sartan）阻斷其受體。可能使血鉀上升。","c":"14.2、14.7","f":"兩者都阻斷血管收縮素 II 的作用 → 血管擴張、醛固酮減少 → 血壓下降，並保護腎臟（降低腎絲球內壓、減少蛋白尿）與心臟。ACE 抑制劑藥名 -pril；ARB 藥名 -sartan，不會累積緩激肽，較少乾咳。","e":"因醛固酮減少，可能<b>高血鉀</b>，尤其合併慢性腎臟病或使用保鉀利尿劑時；這類病人要注意高鉀食物與低鈉鹽（含鉀）。","m":"<b>-pril 擋 ACE、-sartan 擋受體；都可能高血鉀</b>。","en":"ACE inhibitor|ACE 抑制劑;ARB=angiotensin II receptor blocker|血管收縮素 II 受體阻斷劑;dry cough|乾咳;hyperkalemia|高血鉀"},
"natriuresis":{"t":"利鈉作用 natriuresis","d":"腎臟把更多鈉排到尿中；因為水跟著鈉走，尿量也會增加。","c":"14.2","f":"促進：ANP／BNP、多巴胺、血壓上升時的壓力利鈉、利尿劑；抑制：醛固酮、血管收縮素 II、交感神經。","m":"<b>natri-＝鈉、-uresis＝排尿</b>。","en":"natriuresis|利鈉作用;sodium excretion|鈉排泄;ANP|心房利鈉胜肽"},
"poiseuille":{"t":"泊肅葉定律 Poiseuille's law","d":"流量與壓力差及半徑的四次方成正比，與管長及黏度成反比；半徑減半，流量剩 1/16。","c":"14.3","f":"流量 ∝ ΔP × r⁴／（η × L）。r 是半徑：半徑增加 1 倍，流量增加 16 倍。所以身體主要靠小動脈管徑來調節血流與阻力；血液黏度（η）與血管長度（L）通常較少變化。","e":"冠狀動脈狹窄一半，在相同壓力下血流可能剩不到原本的 1/10。","m":"<b>半徑的四次方</b>。","en":"Poiseuille's law|泊肅葉定律;radius to the fourth power|半徑的四次方;vessel length|血管長度;viscosity|黏度"},
"viscosity":{"t":"黏度 viscosity","d":"液體的濃稠程度；血液黏度主要由血比容決定，紅血球增多或脫水時增加。","c":"14.3","f":"血比容越高，血液越黏，流動阻力越大、心臟負擔越重；貧血時黏度下降、阻力降低。","e":"高海拔、慢性缺氧、使用 EPO 或紅血球增多症使血液過黏，增加血栓風險；嚴重脫水也會。","m":"<b>紅血球越多，血越黏</b>。","en":"viscosity|黏度;hematocrit|血比容;polycythemia|紅血球增多症"},
"vasocon":{"t":"血管收縮、血管擴張 vasoconstriction / vasodilation","d":"血管平滑肌收縮使管徑變小、阻力增加；放鬆使管徑變大、阻力減少、血流增加。","c":"14.3","f":"<b>收縮</b>：交感神經（α₁）、血管收縮素 II、ADH、內皮素、血栓素、寒冷。<b>擴張</b>：一氧化氮、前列環素、緩激肽、組織胺、ANP、局部代謝產物（CO₂、H⁺、腺苷、K⁺）、β₂（骨骼肌血管）、溫熱。","m":"<b>縮→阻力↑血壓↑；擴→血流↑</b>。","en":"vasoconstriction|血管收縮;vasodilation|血管擴張;vascular resistance|血管阻力"},
"autoreg":{"t":"自動調節 autoregulation","d":"器官自己控制自己的血流：血壓高一點低一點，血流都保持穩定。","c":"14.3、14.5","f":"在平均動脈壓約 60–160 mmHg 的範圍內有效；腦、腎臟、心臟的自動調節特別好。機制：肌原性（被撐開就收縮）與代謝性（代謝產物使血管擴張）。","e":"血壓降太低或太快（例如高血壓病人急速降壓、休克）超出範圍 → 腦與腎血流不足。","m":"<b>器官自己的水龍頭</b>。","en":"autoregulation|自動調節;intrinsic control|內在控制;constant blood flow|恆定血流"},
"myogenic":{"t":"肌原性調節 myogenic regulation","d":"血管被血壓撐開時平滑肌反射性收縮、血壓降時放鬆，維持血流穩定。","c":"14.3","f":"血壓上升撐開小動脈 → 平滑肌的牽張敏感通道打開 → 去極化、Ca²⁺ 進入 → 收縮 → 管徑變小 → 血流恢復；血壓下降則放鬆。","m":"<b>被撐就縮、鬆了就張</b>。","en":"myogenic regulation|肌原性調節;stretch-induced contraction|伸張誘發收縮;vascular smooth muscle|血管平滑肌"},
"metabolicreg":{"t":"代謝性調節 metabolic regulation","d":"組織代謝旺盛時，O₂↓、CO₂、H⁺、K⁺、腺苷↑使局部小動脈擴張，血流增加。","c":"14.3","f":"組織越忙，產生越多 CO₂、H⁺、乳酸、K⁺、腺苷，消耗越多 O₂ → 這些變化直接使該處小動脈與微血管前括約肌放鬆 → 血流自動配合需求增加。","e":"運動時肌肉血流可增加 20 倍以上，主要靠代謝性調節；飯後腸胃血流增加也是。","m":"<b>越忙，血管越開</b>。","en":"metabolic regulation|代謝性調節;adenosine|腺苷;CO₂|二氧化碳;H⁺|氫離子;K⁺|鉀離子"},
"hyperemia":{"t":"充血 hyperemia","d":"局部血流增加：<b>主動充血</b>（運動時代謝增加）；<b>反應性充血</b>（血流被阻斷一段時間後恢復時血流大增）。","c":"14.3","f":"<b>主動充血</b>：組織活動增加 → 代謝產物 → 血管擴張（運動的肌肉、飯後的腸道）。<b>反應性充血</b>：血流暫時被阻斷（壓迫、止血帶）→ 代謝產物累積 → 恢復時血流大增，皮膚發紅。","m":"<b>主動因為用得多；反應性因為欠得多</b>。","en":"active hyperemia|主動充血;reactive hyperemia|反應性充血;increased blood flow|血流增加"},
"cgmp":{"t":"cGMP（環鳥苷單磷酸）","d":"NO 活化鳥苷酸環化酶產生的第二傳訊者，使血管平滑肌放鬆；威而鋼抑制其分解。","c":"14.3；第 6 章","f":"一氧化氮擴散進平滑肌 → 活化可溶性鳥苷酸環化酶 → GTP → cGMP → 活化蛋白質激酶 G → 降低細胞內 Ca²⁺、活化肌凝蛋白輕鏈磷酸酶 → 平滑肌放鬆、血管擴張。由磷酸二酯酶（PDE5）分解。","e":"硝化甘油提供 NO；威而鋼（sildenafil）抑制 PDE5；兩者合用會使血壓嚴重下降，禁止同時使用。","m":"<b>NO → cGMP → 放鬆</b>。","en":"cGMP=cyclic guanosine monophosphate|環鳥苷單磷酸;guanylate cyclase|鳥苷酸環化酶;nitric oxide|一氧化氮"},
"coronary":{"t":"冠狀動脈、冠狀循環 coronary circulation","d":"從主動脈根部發出供應心肌的動脈；心肌取氧率約 75%，需氧增加只能靠增加冠狀血流；左心室血流主要在心舒期。","c":"14.4；第 13 章","f":"左、右冠狀動脈從主動脈根部（主動脈瓣上方）發出；左冠狀動脈分出前降支與迴旋支。左心室的血流主要在<b>心舒期</b>流入（收縮時心肌擠壓血管）。心肌靜止時就已抽取約 75% 的氧，所以需氧增加時只能靠增加血流。","e":"心跳太快縮短心舒期 → 冠狀動脈灌流時間減少 → 容易誘發心絞痛。","m":"<b>心臟在放鬆時才吃飯</b>。","en":"coronary circulation|冠狀循環;coronary arteries|冠狀動脈;left anterior descending artery|左前降支;myocardial perfusion|心肌灌流"},
"avanast":{"t":"動靜脈吻合 arteriovenous anastomoses","d":"皮膚裡的「捷徑血管」，讓血液不經過微血管直接從小動脈流到小靜脈，用來調節體溫。","c":"14.5","f":"受交感神經控制：寒冷時收縮 → 皮膚血流減少、保留熱量；炎熱時打開 → 大量溫暖血液流經皮膚散熱。","e":"天冷時手指、耳朵變白發冷，天熱或喝酒時變紅。","m":"<b>皮膚的散熱開關</b>。","en":"arteriovenous anastomoses|動靜脈吻合;skin blood flow|皮膚血流;thermoregulation|體溫調節"},
"bradykinin":{"t":"緩激肽 bradykinin","d":"由血漿蛋白切出的胜肽，強力擴張血管、增加通透性並引起疼痛；被 ACE 分解（ACE 抑制劑的乾咳副作用與此有關）。","c":"14.5","f":"由激肽原經激肽釋放酶切出：使血管擴張（經 NO 與前列腺素）、增加微血管通透性（腫）、刺激痛覺神經（痛），參與發炎反應。被 ACE 分解失活。","e":"ACE 抑制劑使緩激肽累積 → 乾咳；少數人出現嚴重的血管性水腫。","m":"<b>緩激肽：擴、漏、痛</b>。","en":"bradykinin|緩激肽;vasodilator|血管擴張劑;kinin|激肽;pain|疼痛"},
"baro":{"t":"壓力感受器 baroreceptors","d":"頸動脈竇（舌咽神經）與主動脈弓（迷走神經）壁上的伸張受器，偵測動脈血壓，傳到延腦。","c":"14.6","f":"血壓升高撐開動脈壁 → 放電頻率增加 → 傳到延腦心血管中樞 → 副交感↑、交感↓ → 心率下降、血管擴張 → 血壓回落；血壓下降時相反。負責<b>秒到分鐘</b>的快速調節，長期會「重新設定」到新的血壓值，所以不能長期控制血壓。","m":"<b>壓力感受器管短期、腎臟與 RAAS 管長期</b>。","en":"baroreceptors|壓力感受器;stretch receptors|伸張受器;blood pressure regulation|血壓調節"},
"carotidsinus":{"t":"頸動脈竇、主動脈弓","d":"<b>頸動脈竇</b>：頸總動脈分叉處內頸動脈起端的膨大，有壓力感受器（舌咽神經）。<b>主動脈弓</b>：主動脈彎曲處（迷走神經）。注意化學感受器在頸動脈體與主動脈體（第 16 章）。","c":"14.6","w":"頸動脈竇：頸部兩側、頸總動脈分叉處的內頸動脈起點；主動脈弓：心臟上方。附近的頸動脈體與主動脈體則是偵測血氧的化學感受器。","f":"頸動脈竇的訊號經舌咽神經（IX）、主動脈弓經迷走神經（X）傳到延腦。","e":"用力按壓頸動脈竇可能使心跳變慢甚至昏倒（頸動脈竇過敏），長者尤其要小心；醫師有時按摩頸動脈竇終止某些心搏過速。","m":"<b>竇走 IX、弓走 X</b>。","en":"carotid sinus|頸動脈竇;aortic arch|主動脈弓;glossopharyngeal nerve|舌咽神經;vagus nerve|迷走神經"},
"orthostatic":{"t":"姿勢性（直立性）低血壓 orthostatic hypotension","d":"由躺或坐突然站起時血壓明顯下降而頭暈；壓力感受器反射不足、脫水、降壓藥、老年人常見。","c":"14.6","f":"站起時約 500–800 mL 血液積在下肢 → 回心血量與心輸出量下降 → 正常時壓力感受器反射在幾秒內加快心跳、收縮血管補償；反射不足時收縮壓下降 ≥ 20 mmHg 或舒張壓下降 ≥ 10 mmHg → 頭暈、眼前發黑、跌倒。","e":"常見於長者、脫水、降血壓藥或利尿劑使用者、糖尿病自主神經病變、長期臥床；建議慢慢起身、足夠水分。","m":"<b>站起來血壓掉 → 頭暈</b>。","en":"orthostatic hypotension|姿勢性低血壓;postural hypotension|直立性低血壓;dizziness on standing|起身頭暈"},
"valsalva":{"t":"伐氏操作 Valsalva maneuver","d":"聲門關閉時用力呼氣 → 胸內壓↑ → 靜脈回流↓ → 血壓↓ → 心率反射性↑；放鬆後血壓回衝 → 心率↓。用力排便、舉重憋氣時發生。","c":"14.6（國考）","f":"用力閉氣（像解便、搬重物）→ 胸內壓急升 → 靜脈回流減少 → 心輸出量與血壓下降 → 心率反射性加快；放鬆時血液大量回流 → 血壓暫時衝高 → 心率反射性變慢。","e":"心臟病人解便用力可能誘發心律不整或昏厥，所以要預防便秘（足夠纖維與水分）。","n":"以 17 世紀義大利解剖學家 Antonio Valsalva 命名。","m":"<b>閉氣用力 → 回流少 → 血壓先降後升</b>。","en":"Valsalva maneuver|伐氏操作;forced expiration against a closed glottis|閉聲門用力呼氣;straining|用力解便"},
"bainbridge":{"t":"班布里奇反射 Bainbridge reflex","d":"右心房被大量回流的血撐開時，心跳會自動加快，把多出來的血快點打出去。","c":"14.6","f":"心房壁的牽張感受器 → 迷走神經傳入 → 延腦 → 交感↑ → 心率↑。與壓力感受器反射相反（後者在血壓高時減慢心率），兩者的平衡決定實際心率。","m":"<b>心房被撐 → 心跳加快</b>。","en":"Bainbridge reflex|班布里奇反射;atrial reflex|心房反射;increased venous return|靜脈回流增加"},
"korotkoff":{"t":"柯氏音 sounds of Korotkoff","d":"以壓脈帶量血壓時，血液斷續通過被壓扁的動脈產生亂流的聲音：出現＝收縮壓，消失＝舒張壓。","c":"14.6","f":"壓脈帶壓力高於收縮壓時動脈完全被壓扁、沒有聲音；慢慢放氣到剛好等於收縮壓時，血液斷續擠過 → 出現第一聲（<b>收縮壓</b>）；壓力降到低於舒張壓時動脈不再被壓扁、血流恢復平順 → 聲音消失（<b>舒張壓</b>）。","m":"<b>第一聲＝收縮壓、聲音消失＝舒張壓</b>。","en":"sounds of Korotkoff|柯氏音;sphygmomanometer|血壓計;auscultation|聽診"},
"sbp":{"t":"收縮壓、舒張壓 systolic / diastolic pressure","d":"<b>收縮壓</b>：心室射血時動脈壓的最高值（約 120）。<b>舒張壓</b>：心舒期動脈壓的最低值（約 80）。","c":"14.6","f":"收縮壓主要反映心搏量與大動脈的彈性；舒張壓主要反映總周邊阻力與心跳快慢。","e":"老化使動脈變硬 → 收縮壓上升、舒張壓下降或不變（單純收縮期高血壓）。","m":"<b>上面的數字＝收縮壓、下面＝舒張壓</b>。","en":"systolic pressure|收縮壓;diastolic pressure|舒張壓;mmHg|毫米汞柱;120/80|一百二十／八十"},
"pulsepressure":{"t":"脈壓 pulse pressure","d":"收縮壓－舒張壓（約 40 mmHg）；摸到的脈搏即由此產生；動脈硬化時變大。","c":"14.6","f":"每次射血使動脈壓起伏的幅度；心搏量越大、動脈越硬，脈壓越大。","e":"脈壓大（例如 160/70）常見於動脈硬化的長者、主動脈瓣閉鎖不全、甲狀腺亢進；脈壓很小可能表示心搏量很低（休克、心衰竭）。","m":"<b>脈壓＝上－下</b>。","en":"pulse pressure|脈壓;systolic minus diastolic|收縮壓減舒張壓;arterial stiffness|動脈硬度"},
"map":{"t":"平均動脈壓 mean arterial pressure","d":"≈ 舒張壓＋1/3 脈壓（120/80 約 93 mmHg），推動血液到各器官的平均壓力；≈ 心輸出量 × 總周邊阻力。","c":"14.6","f":"因為心舒期比心縮期長，平均動脈壓比較接近舒張壓：MAP ≈ 舒張壓＋（收縮壓－舒張壓）／3。MAP＝心輸出量 × 總周邊阻力。","e":"維持器官灌流通常需要 MAP ≥ 60–65 mmHg；加護病房以此作為治療目標。","m":"<b>MAP ≈ 下＋1/3 脈壓</b>。","en":"MAP=mean arterial pressure|平均動脈壓;diastolic plus one third pulse pressure|舒張壓加三分之一脈壓;organ perfusion|器官灌流"},
"htn":{"t":"高血壓 hypertension","d":"血壓持續偏高：簡報定義 ≥ 140/90 mmHg；台灣 2022 指引 ≥ 130/80 mmHg。九成以上為原發性；多無症狀卻損傷心、腦、腎與血管。","c":"14.7","f":"長期高血壓損傷血管內皮、加速動脈硬化，並使心臟後負荷增加。","e":"標的器官損害：心臟（左心室肥厚、心衰竭、冠心病）、腦（中風）、腎臟（腎硬化、慢性腎臟病）、眼睛（視網膜病變）。生活型態：減重、減鈉、DASH 飲食、規律運動、限酒、戒菸。","m":"<b>沉默的殺手</b>：心、腦、腎、眼。","en":"hypertension|高血壓;high blood pressure|高血壓;130/80|一百三十／八十;silent killer|沉默殺手"},
"essentialhtn":{"t":"原發性、續發性高血壓","d":"高血壓依原因分兩類：找不到單一原因的原發性（大多數），以及由其他疾病引起的續發性。","c":"14.7","f":"<b>原發性</b>：遺傳、高鈉、肥胖、胰島素阻抗、交感過度活化、腎臟排鈉能力下降、年齡。<b>續發性</b>：慢性腎臟病、腎動脈狹窄、原發性醛固酮症、庫欣氏症、嗜鉻細胞瘤、甲狀腺疾病、睡眠呼吸中止症、藥物（類固醇、口服避孕藥、NSAIDs）。","e":"年輕人、突然發作或難以控制的高血壓，要檢查續發性原因。","m":"<b>原發找不到原因、續發找得到原因</b>。","en":"essential hypertension|原發性高血壓;primary hypertension|原發性高血壓;secondary hypertension|續發性高血壓;renal artery stenosis|腎動脈狹窄"},
"dash":{"t":"DASH 飲食","d":"Dietary Approaches to Stop Hypertension：多蔬果、全穀、低脂乳品、堅果豆類（富含鉀、鎂、鈣與纖維），少飽和脂肪、紅肉與甜食，配合減鈉。","c":"14.7","f":"富含鉀、鎂、鈣與膳食纖維，飽和脂肪與添加糖少；配合減鈉時降壓效果更好。原理：鉀促進排鈉並使血管放鬆、鈣與鎂參與血管張力調節、減重與高纖改善胰島素阻抗。","e":"做法：每天多份蔬菜水果、以全穀取代精製穀、選低脂乳品、每天一份堅果、少紅肉與加工肉、少含糖飲料。腎功能不佳者要注意鉀與磷，不能直接套用。","m":"<b>多蔬果、全穀、低脂奶、堅果豆，少鹽少紅肉</b>。","en":"DASH=Dietary Approaches to Stop Hypertension|得舒飲食;fruits and vegetables|蔬果;low-fat dairy|低脂乳品;potassium|鉀;sodium reduction|減鈉"},
"diuretic":{"t":"利尿劑 diuretics","d":"增加腎臟排鈉與排水的藥物，降低血容積與血壓；部分會使鉀流失（需注意低血鉀），保鉀型則可能使鉀升高。","c":"14.7；第 17 章","f":"<b>Thiazide 類</b>（遠曲小管）：常用降壓藥，排鉀、留鈣。<b>環利尿劑</b>（亨利氏環上升枝，furosemide）：最強，用於水腫、心衰竭，排鉀、排鈣。<b>保鉀利尿劑</b>（螺內酯、amiloride，集尿管）：不排鉀。","e":"使用排鉀型利尿劑要注意低血鉀（多吃蔬果）、低血鎂；thiazide 可能使血糖、尿酸升高。","m":"<b>環最強、thiazide 降壓、保鉀不排鉀</b>。","en":"diuretics|利尿劑;thiazide|噻嗪類;loop diuretic|環利尿劑;potassium-sparing|保鉀"},
"betablocker":{"t":"β 阻斷劑 β-blockers","d":"阻斷 β₁ 受體：減慢心率、降低收縮力與腎素分泌；用於高血壓、心絞痛、心衰竭、心律不整。","c":"14.7","m":"<b>藥名 -olol</b>；可能掩蓋低血糖症狀。","en":"beta-blockers|β 阻斷劑;reduce heart rate|降低心率;reduce renin|減少腎素"},
"ccb":{"t":"鈣通道阻斷劑 calcium channel blockers","d":"阻斷血管平滑肌（與心肌）的 L 型鈣通道，使血管放鬆擴張、降低血壓；葡萄柚汁會影響部分藥物的代謝。","c":"14.7","f":"<b>Dihydropyridine 類</b>（amlodipine、nifedipine）：主要作用在血管 → 擴張、降壓，可能引起腳踝水腫、臉潮紅。<b>非 dihydropyridine 類</b>（verapamil、diltiazem）：也作用在心臟 → 減慢心率與傳導。","e":"葡萄柚汁抑制腸道代謝酵素（CYP3A4），使部分鈣通道阻斷劑的血中濃度升高，應避免同時大量食用。","m":"<b>-dipine 擴血管</b>；葡萄柚要小心。","en":"calcium channel blockers|鈣通道阻斷劑;amlodipine|氨氯地平;grapefruit juice interaction|葡萄柚汁交互作用"},
"lvh":{"t":"左心室肥大 left ventricular hypertrophy","d":"長期高血壓使左心室後負荷增加，心肌增厚；初期代償，最後可能導致心衰竭與心律不整。","c":"14.7","f":"後負荷長期增加 → 心肌細胞變粗、心室壁增厚 → 初期維持心搏量；但心室變硬、舒張變差，冠狀動脈供血跟不上 → 心律不整、心衰竭、猝死風險增加。","e":"心電圖與心臟超音波可偵測；控制血壓可使肥厚部分回復。","m":"<b>推太重 → 心肌變厚 → 最後變僵</b>。","en":"LVH=left ventricular hypertrophy|左心室肥大;pressure overload|壓力負荷;hypertension|高血壓"},
"shock":{"t":"循環性休克 circulatory shock","d":"組織灌流不足。類型：低血容積性、敗血性、過敏性、神經性、心因性。代償表現：心跳快、皮膚濕冷蒼白、尿少。","c":"14.7","f":"<b>低血容積性</b>：出血、嚴重脫水、燒燙傷。<b>心因性</b>：心肌梗塞、嚴重心律不整。<b>分布性</b>：敗血性、過敏性、神經性（血管廣泛擴張）。<b>阻塞性</b>：肺栓塞、心包填塞。代償：交感興奮（心跳快、皮膚濕冷）、RAAS 與 ADH（尿少）；失代償後細胞缺氧、乳酸中毒、多重器官衰竭。","m":"<b>量不夠、幫浦壞、管子太鬆、路被堵</b>。","en":"circulatory shock|循環性休克;hypovolemic shock|低血容休克;cardiogenic shock|心因性休克;tissue hypoperfusion|組織灌流不足"},
"anaphylaxis":{"t":"過敏性休克 anaphylactic shock","d":"嚴重過敏時大量組織胺使血管擴張、微血管漏液、支氣管收縮；需立即注射腎上腺素。","c":"14.7；第 15 章","f":"過敏原與肥大細胞上的 IgE 結合 → 大量釋放組織胺、白三烯素等 → 全身血管擴張與漏液（血壓驟降）、支氣管收縮（喘鳴）、喉頭水腫、蕁麻疹，數分鐘內就可能致命。","e":"常見誘因：食物（花生、堅果、海鮮、蛋、奶）、藥物、蜂螫。急救首選<b>肌肉注射腎上腺素</b>；食物過敏者要學會看食品標示、隨身攜帶腎上腺素筆。","m":"<b>過敏性休克 → 立刻打腎上腺素</b>。","en":"anaphylactic shock|過敏性休克;anaphylaxis|全身性過敏反應;epinephrine|腎上腺素;EpiPen|腎上腺素自動注射筆"},
"septic":{"t":"敗血性休克 septic shock","d":"嚴重感染時細菌毒素引起大量 NO 與發炎物質，使血管廣泛擴張、通透性增加。","c":"14.7","f":"病原體與毒素引起全身性發炎 → 大量 NO 與細胞激素 → 血管廣泛擴張、微血管漏液、心肌受抑制 → 低血壓、組織灌流不足、乳酸上升，常伴隨凝血異常與多重器官衰竭。","e":"敗血症病人代謝亢進、蛋白質大量分解，需要足夠的熱量與蛋白質支持；病情穩定後儘早腸道營養。","m":"<b>感染 → 血管全開 → 休克</b>。","en":"septic shock|敗血性休克;sepsis|敗血症;endotoxin|內毒素;vasodilation|血管擴張"},
"chf":{"t":"鬱血性心衰竭 congestive heart failure","d":"心輸出量不足；腎臟保鈉保水使血量增加、靜脈壓升高：左心衰竭 → 肺水腫；右心衰竭 → 周邊水腫、肝腫大、頸靜脈怒張。","c":"14.7","f":"心臟打不出足夠的血 → 腎臟感覺「血不夠」→ RAAS、ADH、交感神經活化 → 保鈉保水 → 血量增加 → 靜脈壓與微血管壓升高 → 淤血與水腫。<b>左心衰竭</b>：肺淤血、呼吸困難、端坐呼吸。<b>右心衰竭</b>：下肢水腫、頸靜脈怒張、肝腫大、腹水。","e":"飲食：限鈉、必要時限水、每天量體重（短期體重快速增加代表積水）；注意心臟惡病質（肌肉與體重流失）。","m":"<b>左衰淹肺、右衰淹腳</b>。","en":"CHF=congestive heart failure|鬱血性心衰竭;heart failure|心衰竭;fluid restriction|限水;sodium restriction|限鈉;cardiac cachexia|心因性惡病質"},
"pulmedema":{"t":"肺水腫 pulmonary edema","d":"肺微血管靜水壓升高（左心衰竭）或通透性增加，液體進入肺組織與肺泡，造成呼吸困難。","c":"14.7","f":"左心衰竭使肺靜脈與肺微血管靜水壓升高 → 液體進入肺間質與肺泡 → 氣體交換的距離變長、肺變僵硬 → 呼吸困難、咳出粉紅色泡沫痰、聽診有囉音。也可能因肺微血管受損通透性增加（急性呼吸窘迫症候群）。","m":"<b>肺泡進水 → 換不了氣</b>。","en":"pulmonary edema|肺水腫;left heart failure|左心衰竭;dyspnea|呼吸困難;orthopnea|端坐呼吸"},
"histamine":{"t":"組織胺 histamine","d":"肥大細胞與嗜鹼性球釋放，使血管擴張、微血管通透性增加（紅腫）、支氣管收縮；胃中經 H₂ 受體促進胃酸。","c":"14.7；第 15、18 章","f":"由組胺酸去羧（需 B6）而來；作用在 H₁ 受體：血管擴張、微血管通透性增加（紅、腫、癢）、支氣管收縮；作用在 H₂ 受體：胃酸分泌。","e":"抗組織胺（H₁ 阻斷劑）治療過敏；H₂ 阻斷劑治療胃酸過多。不新鮮的魚（鯖魚、鮪魚）細菌把組胺酸轉成大量組織胺 → 鯖魚中毒（類過敏症狀）。","m":"<b>H₁ 過敏、H₂ 胃酸</b>。","en":"histamine|組織胺;mast cells|肥大細胞;increased capillary permeability|微血管通透性增加;scombroid poisoning|鯖魚中毒"}});
Object.assign(GL_ALIAS,{"心輸出量":"co","心率":"hr","前負荷":"preload","後負荷":"preload","收縮力":"contractility","正變力":"inotropic","變力作用":"inotropic","變時作用":"inotropic","法蘭克—史達林定律":"frankstarling","法蘭克—史達林":"frankstarling","總周邊阻力":"tpr","周邊阻力":"tpr","靜脈回流":"venreturn","史達林力":"starlingf","膠體滲透壓":"oncotic","靜水壓":"hydrostatic","ADH":"adh","血管加壓素":"vasopressin","腎素":"renin","近腎絲球細胞":"jgcell","血管收縮素":"angiotensin","血管收縮素 II":"angiotensin","血管收縮素 I":"angiotensin","血管收縮素原":"angiotensin","ACE":"ace","血管收縮素轉化酶":"ace","RAAS":"raas","腎素—血管收縮素—醛固酮系統":"raas","ACE 抑制劑":"arb","ARB":"arb","利鈉":"natriuresis","泊肅葉定律":"poiseuille","黏度":"viscosity","血管收縮":"vasocon","血管擴張":"vasocon","自動調節":"autoreg","肌原性調節":"myogenic","代謝性調節":"metabolicreg","反應性充血":"hyperemia","cGMP":"cgmp","冠狀動脈":"coronary","冠狀血流":"coronary","冠狀循環":"coronary","動靜脈吻合":"avanast","緩激肽":"bradykinin","壓力感受器":"baro","壓力感受器反射":"baroreflex","頸動脈竇":"carotidsinus","主動脈弓":"carotidsinus","姿勢性低血壓":"orthostatic","直立性低血壓":"orthostatic","伐氏操作":"valsalva","班布里奇反射":"bainbridge","柯氏音":"korotkoff","收縮壓":"sbp","舒張壓":"sbp","脈壓":"pulsepressure","平均動脈壓":"map","高血壓":"htn","原發性高血壓":"essentialhtn","續發性高血壓":"essentialhtn","DASH":"dash","利尿劑":"diuretic","β 阻斷劑":"betablocker","鈣通道阻斷劑":"ccb","左心室肥大":"lvh","休克":"shock","循環性休克":"shock","過敏性休克":"anaphylaxis","敗血性休克":"septic","心衰竭":"chf","鬱血性心衰竭":"chf","肺水腫":"pulmedema","組織胺":"histamine"});

