Object.assign(GL,{"ventilation":{"t":"換氣 ventilation","d":"空氣進出肺的呼吸動作；與氣體交換（擴散）、細胞呼吸合稱呼吸。","c":"16.1","f":"呼吸三步驟：①換氣（空氣進出肺）②氣體交換（肺泡與血液、血液與組織間擴散）③細胞呼吸（粒線體用 O₂ 產生 ATP、放出 CO₂）。換氣量＝潮氣容積 × 呼吸頻率（約 500 mL × 12 次＝6 L/分）。","m":"<b>換氣是搬運，交換靠擴散</b>。","en":"pulmonary ventilation|肺換氣;gas exchange|氣體交換;cellular respiration|細胞呼吸;minute ventilation|每分換氣量"},
"alveoli":{"t":"肺泡 alveoli","d":"約 3 億個小氣囊，總面積約 60–80 m²，壁極薄、外圍密布微血管，是氣體交換的地方。","c":"16.1","w":"呼吸道最末端，呼吸性細支氣管與肺泡管周圍成串排列，像葡萄。","f":"面積大（約一個網球場的一半）、壁薄、血流多，依費克擴散定律讓 O₂ 與 CO₂ 快速擴散。肺泡內還有巨噬細胞（塵細胞）清除微粒。","e":"肺氣腫時肺泡壁破壞、面積變小；肺水腫時液體使擴散距離變長，兩者都造成缺氧。","m":"<b>面積大、壁薄、血多</b>＝擴散三條件。","en":"alveoli|肺泡;alveolus|肺泡（單數）;alveolar macrophages|肺泡巨噬細胞;dust cells|塵細胞"},
"alvcell":{"t":"第一型、第二型肺泡細胞","d":"<b>第一型</b>：極扁平，占表面 95%，與微血管組成約 0.3 µm 的呼吸膜。<b>第二型</b>：分泌表面活性劑。","c":"16.1","w":"肺泡壁上；第一型扁平鋪滿表面，第二型是夾在其中的圓胖細胞。","f":"第一型負責氣體擴散，受傷後不能自行分裂；第二型除了分泌表面活性劑，也會分裂並分化成第一型，負責修補。","m":"<b>一型換氣、二型分泌兼修補</b>。","en":"type I alveolar cells|第一型肺泡細胞;type II alveolar cells|第二型肺泡細胞;respiratory membrane|呼吸膜"},
"condzone":{"t":"傳導區、呼吸區","d":"<b>傳導區</b>：鼻到終末細支氣管，送氣、加溫、加濕、過濾，不交換氣體。<b>呼吸區</b>：呼吸性細支氣管、肺泡管、肺泡，進行交換。","c":"16.1","f":"傳導區約 150 mL，就是解剖死腔。鼻腔讓空氣在到達肺泡前變成體溫、水蒸氣飽和並濾除大部分微粒。","e":"用嘴巴呼吸或氣切的人，空氣沒有經過鼻腔加濕，呼吸道容易乾、痰變黏，需要額外加濕。","m":"<b>傳導區送氣不交換、呼吸區才交換</b>。","en":"conducting zone|傳導區;respiratory zone|呼吸區;terminal bronchioles|終末細支氣管;respiratory bronchioles|呼吸性細支氣管"},
"mucocil":{"t":"黏液纖毛電扶梯 mucociliary escalator","d":"呼吸道杯狀細胞分泌黏液黏住微粒，纖毛把黏液往咽部推送；抽菸破壞纖毛。","c":"16.1","w":"氣管、支氣管到細支氣管的上皮（偽複層纖毛柱狀上皮）。","f":"黏液層上層黏、下層稀；纖毛在稀的那層中擺動，把黏液連同灰塵細菌以每分鐘數毫米速度往上推到咽部，再咳出或吞下。","e":"抽菸麻痺並破壞纖毛 → 痰積在肺 → 晨咳（抽菸者咳）；囊狀纖維化病人黏液過稠也無法清除，且常伴胰臟分泌不足需補充胰酵素與脂溶性維生素。維生素 A 缺乏使呼吸道上皮角質化、纖毛減少。","m":"<b>黏液黏、纖毛推，像電扶梯往上送</b>。","en":"mucociliary escalator|黏液纖毛電扶梯;goblet cells|杯狀細胞;cystic fibrosis|囊狀纖維化;smoker's cough|抽菸者咳"},
"pleura":{"t":"胸膜、胸膜腔 pleura","d":"臟層胸膜覆蓋肺、壁層胸膜覆蓋胸壁，中間的胸膜腔只有一層液體，使肺貼著胸壁擴張。","c":"16.1","f":"兩層胸膜間的少量液體產生表面張力，讓肺「黏」在胸壁上，胸壁擴張時肺跟著擴張；同時潤滑減少摩擦。","e":"肋膜積水（胸水）會壓迫肺；胸膜發炎時深呼吸會刺痛。","m":"<b>兩層玻璃片中間一滴水，拉不開但滑得動</b>。","en":"pleura|胸膜;visceral pleura|臟層胸膜;parietal pleura|壁層胸膜;pleural cavity|胸膜腔;pleural effusion|肋膜積水"},
"pneumothorax":{"t":"氣胸 pneumothorax","d":"空氣進入胸膜腔，胸膜內負壓消失，肺因彈性回縮而塌陷。","c":"16.1","f":"胸壁受傷（外傷性）或肺表面小氣泡破裂（自發性）→ 空氣進入胸膜腔 → 胸膜內壓變成與大氣相同 → 肺失去被撐開的力量而塌陷。","e":"自發性氣胸常見於瘦高的年輕男性與抽菸者；突發胸痛、呼吸困難，嚴重時需插胸管引流。","n":"pneumo-（空氣）＋ thorax（胸）。","m":"<b>負壓沒了，肺就縮回去</b>。","en":"pneumothorax|氣胸;collapsed lung|肺塌陷;chest tube|胸管"},
"boyle":{"t":"波以耳定律 Boyle's law","d":"溫度不變時，氣體的壓力與體積成反比；胸腔變大 → 肺內壓下降 → 空氣流入。","c":"16.2","f":"吸氣：橫膈與外肋間肌收縮 → 胸腔體積變大 → 肺內壓低於大氣壓 → 空氣流入。呼氣：肌肉放鬆、肺彈回 → 體積變小 → 肺內壓高於大氣 → 空氣流出。","n":"17 世紀英國科學家 Robert Boyle 提出。","m":"<b>P × V＝定值：體積大、壓力小</b>。","en":"Boyle's law|波以耳定律;pressure is inversely proportional to volume|壓力與體積成反比;inspiration|吸氣;expiration|呼氣"},
"intrapulm":{"t":"肺內壓、胸膜內壓","d":"<b>肺內壓</b>：肺泡內壓力，吸氣約 −3、呼氣約 +3 mmHg（相對大氣）。<b>胸膜內壓</b>：始終低於肺內壓（約 −3 到 −6），兩者差撐開肺。","c":"16.2","f":"胸膜內壓為負，是因為肺想往內縮、胸壁想往外彈，兩股力量把中間的胸膜腔往外拉。肺內壓與胸膜內壓的差（跨肺壓）把肺撐開。","m":"<b>胸膜內壓永遠是負的</b>（除非氣胸或用力呼氣）。","en":"intrapulmonary pressure|肺內壓;intrapleural pressure|胸膜內壓;transpulmonary pressure|跨肺壓;subatmospheric|低於大氣壓"},
"compliance":{"t":"順應性 compliance","d":"肺容易被撐開的程度；肺纖維化時下降，吸氣費力；肺氣腫時反而上升。","c":"16.2","f":"順應性＝肺容積變化／跨肺壓變化。順應性高：容易吹脹但不容易彈回（肺氣腫）。順應性低：吹不太脹，吸氣肌要更用力（纖維化、表面活性劑不足、肺水腫）。","m":"<b>順應性＝好不好吹；彈性＝好不好彈回</b>（兩者相反）。","en":"compliance|順應性;lung compliance|肺順應性;distensibility|可擴張性"},
"lungelastic":{"t":"肺的彈性 elasticity","d":"肺被撐開後彈回的傾向，來自彈性蛋白纖維與表面張力；平靜呼氣靠它；肺氣腫時被破壞。","c":"16.2","f":"來源：①肺組織中的彈性蛋白纖維；②肺泡內表面張力（佔比較大）。平靜呼氣不需要肌肉，靠肺彈回。","e":"肺氣腫時彈性蛋白被嗜中性球的彈性蛋白酶分解，呼氣要靠用力；先天 α₁-抗胰蛋白酶缺乏的人特別容易早發肺氣腫。","m":"<b>吸氣靠肌肉、平靜呼氣靠彈回</b>。","en":"elasticity|彈性;elastic recoil|彈性回縮;elastin|彈性蛋白;α1-antitrypsin deficiency|α1-抗胰蛋白酶缺乏"},
"surfacetension":{"t":"表面張力 surface tension","d":"肺泡內表面水分子互相吸引使肺泡傾向塌陷；依拉普拉斯定律（P＝2T/r）小肺泡更易塌陷。","c":"16.2","f":"肺泡內有一層薄水膜，水分子互相拉扯，讓肺泡想縮小。依拉普拉斯定律，半徑小的肺泡內壓較高，若沒有表面活性劑，空氣會從小肺泡流到大肺泡，小肺泡塌陷。","n":"拉普拉斯定律以 18 世紀法國數學家 Pierre-Simon Laplace 命名。","m":"<b>小泡壓力大，容易塌</b>。","en":"surface tension|表面張力;law of Laplace|拉普拉斯定律;alveolar collapse|肺泡塌陷"},
"surfactant":{"t":"表面活性劑 surfactant","d":"第二型肺泡細胞分泌的磷脂質（主要 DPPC）與蛋白，降低表面張力、防止肺泡塌陷；胎兒約 28–32 週後足量分泌。","c":"16.2","w":"由第二型肺泡細胞的層狀體分泌到肺泡內表面的水膜上。","f":"插在水分子之間減弱它們互相吸引的力量；肺泡越小時活性劑越密集、表面張力降得越多，讓大小肺泡穩定共存、呼氣時不塌陷，也讓吸氣比較省力。","e":"主要成分 DPPC（雙棕櫚醯磷脂醯膽鹼）需要膽素合成；產前給母親類固醇可加速胎兒肺成熟。","m":"<b>表面活性劑＝肺泡的洗碗精</b>。","en":"surfactant|表面活性劑;DPPC=dipalmitoylphosphatidylcholine|雙棕櫚醯磷脂醯膽鹼;phospholipid|磷脂質;lung maturity|肺成熟"},
"rds":{"t":"呼吸窘迫症候群 respiratory distress syndrome","d":"早產兒缺乏表面活性劑，肺泡反覆塌陷、呼吸費力（透明膜疾病）；以人工表面活性劑與呼吸器治療，產前類固醇可預防。成人嚴重肺損傷時為 ARDS。","c":"16.2","f":"沒有表面活性劑 → 肺泡每次呼氣都塌陷 → 每次吸氣都要像吹新氣球一樣用力 → 呼吸窘迫、缺氧；肺泡內形成蛋白質的透明膜。","e":"早產兒呼吸費力消耗大量熱量，常需要高熱量的早產兒配方或強化母乳，並注意液體不要過多加重肺水腫。","m":"<b>早產＋沒有洗碗精 → 肺泡吹不開</b>。","en":"RDS=respiratory distress syndrome|呼吸窘迫症候群;hyaline membrane disease|透明膜疾病;ARDS=acute respiratory distress syndrome|急性呼吸窘迫症候群;premature infant|早產兒"},
"diaphragm":{"t":"橫膈 diaphragm","d":"胸腔與腹腔之間的圓頂狀骨骼肌，收縮時下降擴大胸腔，是最主要的吸氣肌，由膈神經（C3–C5）支配。","c":"16.3","w":"胸腔底部，像一頂往上凸的圓頂帳篷，邊緣附著在肋骨、胸骨、腰椎。","f":"收縮時圓頂往下拉平 → 胸腔上下變長；平靜吸氣約 75% 靠橫膈。食道、主動脈、下腔靜脈穿過它進入腹腔。","e":"橫膈痙攣就是打嗝；頸椎 C5 以上脊髓損傷可能癱瘓橫膈，需要呼吸器。食道從橫膈裂孔往上滑入胸腔就是裂孔疝氣，常伴胃食道逆流。","m":"<b>C3、4、5 讓橫膈活著（keeps the diaphragm alive）</b>。","en":"diaphragm|橫膈;phrenic nerve|膈神經;hiatal hernia|裂孔疝氣;hiccup|打嗝"},
"intercostal":{"t":"外肋間肌、內肋間肌","d":"<b>外肋間肌</b>：吸氣時上提肋骨。<b>內肋間肌</b>：用力呼氣時下降肋骨。","c":"16.3","f":"平靜吸氣：橫膈＋外肋間肌。用力吸氣：再加胸鎖乳突肌、斜角肌、胸小肌。平靜呼氣：被動。用力呼氣：內肋間肌＋腹肌（把橫膈往上推）。","e":"COPD 病人常用到頸部輔助呼吸肌，呼吸做功大、靜止能量消耗增加，容易體重下降。","m":"<b>外吸內呼</b>。","en":"external intercostal muscles|外肋間肌;internal intercostal muscles|內肋間肌;accessory muscles|輔助呼吸肌"},
"tidal":{"t":"潮氣容積 tidal volume","d":"平靜時一次吸入或呼出的氣量，約 500 mL。","c":"16.3","f":"其中約 150 mL 停在死腔，只有約 350 mL 到達肺泡進行交換。","m":"<b>潮氣＝像潮水平靜進出，500 mL</b>。","en":"tidal volume|潮氣容積;500 mL|500 毫升;quiet breathing|平靜呼吸"},
"lungvol":{"t":"肺容積與肺容量","d":"肺可以裝的氣分成 4 個「基本格子」（容積），容量是兩個以上格子加起來。","c":"16.3","m":"<b>容積是基本格，容量是相加</b>；有 RV 的（FRC、TLC）肺量計測不到。","en":"TV=tidal volume|潮氣容積;IRV=inspiratory reserve volume|吸氣儲備容積;ERV=expiratory reserve volume|呼氣儲備容積;RV=residual volume|殘氣容積;TLC=total lung capacity|總肺容量;spirometry|肺量計"},
"vc":{"t":"肺活量 vital capacity","d":"盡力吸氣後盡力呼出的最大量＝IRV＋TV＋ERV，約 4,700 mL；限制性肺病時下降。","c":"16.3","f":"受年齡、性別、身高、姿勢影響；神經肌肉疾病（肌肉無力）、肺纖維化、脊柱側彎、腹部脹大都會降低。","m":"<b>VC＝IRV＋TV＋ERV</b>（除了殘氣以外全部）。","en":"vital capacity|肺活量;IRV plus TV plus ERV|吸氣儲備加潮氣加呼氣儲備"},
"rv":{"t":"殘氣容積 residual volume","d":"盡力呼氣後仍留在肺內的氣量（約 1,200 mL），肺量計測不到；肺氣腫時增加。","c":"16.3","f":"肺不可能完全排空（呼吸道會先塌陷、胸壁也不能無限縮小），留下的氣讓肺泡保持張開、讓呼氣時血液仍能持續交換氣體。","e":"肺氣腫時呼氣受阻，氣體被困在肺內（空氣滯留）→ RV 與 TLC 增加 → 胸廓變成桶狀胸。","m":"<b>殘氣＝怎麼吐都吐不掉的</b>。","en":"residual volume|殘氣容積;air trapping|空氣滯留;barrel chest|桶狀胸"},
"frc":{"t":"功能肋餘容量 functional residual capacity","d":"平靜呼氣後留在肺內的量＝ERV＋RV（約 2,400 mL），使肺泡氣體組成保持穩定。","c":"16.3","f":"每次只吸入約 350 mL 新鮮空氣到 2,400 mL 的肺泡氣中，所以肺泡氣的 PO₂、PCO₂ 每次呼吸只稍微變動，血氣得以穩定。也是肺與胸壁回彈力平衡的位置。","m":"<b>FRC＝ERV＋RV，平靜呼氣後剩下的</b>。","en":"FRC=functional residual capacity|功能肋餘容量;ERV plus RV|呼氣儲備加殘氣"},
"deadspace":{"t":"死腔 dead space","d":"傳導區中不參與氣體交換的空間，約 150 mL；肺泡換氣量＝（潮氣容積－死腔）× 頻率。","c":"16.3","f":"解剖死腔：傳導區。生理死腔：解剖死腔＋有通氣但沒血流的肺泡。淺而快的呼吸死腔比例高，換氣效率差；深而慢的呼吸效率較好。","e":"例：潮氣 500、頻率 12 → 肺泡換氣 (500−150)×12＝4.2 L/分；若潮氣 250、頻率 24 → (250−150)×24＝2.4 L/分，總換氣一樣但肺泡換氣少很多。","m":"<b>先扣死腔再乘頻率</b>。","en":"anatomical dead space|解剖死腔;physiological dead space|生理死腔;alveolar ventilation|肺泡換氣量"},
"fev1":{"t":"FEV₁、FEV₁/FVC","d":"第一秒用力呼氣量與用力肺活量的比值，正常 ≥ 約 0.8；阻塞性肺病下降。","c":"16.3","f":"請病人吸飽後用最大力氣、最快速度吐氣；正常人第一秒能吐出 FVC 的 80% 以上。阻塞性：FEV₁ 下降比 FVC 多 → 比值 &lt; 0.7（COPD 診斷標準）。限制性：兩者都下降 → 比值正常甚至偏高。","m":"<b>比值低＝阻塞；比值正常但量小＝限制</b>。","en":"FEV₁=forced expiratory volume in one second|第一秒用力呼氣量;FVC=forced vital capacity|用力肺活量;FEV₁/FVC ratio|FEV₁ 與 FVC 比值"},
"restrictive":{"t":"限制性、阻塞性肺病","d":"<b>限制性</b>：肺無法充分擴張（纖維化），VC↓、FEV₁/FVC 正常。<b>阻塞性</b>：呼氣氣流受阻（氣喘、肺氣腫、慢性支氣管炎），FEV₁/FVC↓。","c":"16.3","e":"限制性也包括肺外原因：嚴重肥胖、脊柱側彎、神經肌肉疾病（漸凍症）。肥胖者減重可改善肺容積。","m":"<b>限制＝吸不進去；阻塞＝吐不出來</b>。","en":"restrictive lung disease|限制性肺病;obstructive lung disease|阻塞性肺病;pulmonary function test|肺功能檢查"},
"asthma":{"t":"氣喘 asthma","d":"呼吸道慢性發炎，支氣管平滑肌對刺激過度反應而收縮（白三烯素、組織胺），通常可逆；以 β₂ 致效劑與吸入型類固醇治療。","c":"16.3","f":"過敏原或刺激物 → 肥大細胞與嗜酸性球釋放組織胺、白三烯素 → 支氣管平滑肌收縮、黏膜水腫、黏液增加 → 氣流受阻（呼氣時喘鳴聲）。急性發作用短效 β₂ 致效劑擴張支氣管；長期控制用吸入型類固醇抗發炎。","e":"肥胖會增加氣喘風險與嚴重度；長期口服類固醇者需注意骨質與血糖。阿斯匹靈可能誘發部分人氣喘（白三烯素增加）。","m":"<b>氣喘＝發炎＋收縮，可逆</b>。","en":"asthma|氣喘;bronchoconstriction|支氣管收縮;wheezing|喘鳴;β2 agonist|β2 致效劑;inhaled corticosteroid|吸入型類固醇"},
"emphysema":{"t":"肺氣腫 emphysema","d":"肺泡壁被破壞、融合成大氣囊，交換面積減少、彈性喪失、呼氣時細支氣管塌陷；主因抽菸，屬阻塞性。","c":"16.3","f":"抽菸 → 肺內嗜中性球與巨噬細胞釋放彈性蛋白酶，超過 α₁-抗胰蛋白酶的保護 → 肺泡壁被分解 → 面積減少（缺氧）、彈性喪失（細支氣管在呼氣時失去牽拉而塌陷、空氣滯留）。","e":"典型病人瘦、桶狀胸、噘嘴呼吸（增加呼氣時呼吸道壓力防止塌陷），俗稱「粉紅吹氣者」。","n":"希臘文 emphysan＝「吹進去」，肺裡充滿空氣。","m":"<b>肺泡壁破、彈性沒、氣卡住</b>。","en":"emphysema|肺氣腫;alveolar destruction|肺泡破壞;elastase|彈性蛋白酶;pursed-lip breathing|噘嘴呼吸;pink puffer|粉紅吹氣者"},
"copd":{"t":"慢性阻塞性肺病 COPD","d":"慢性支氣管炎與肺氣腫的合稱，呼氣氣流受阻、不完全可逆；病人常體重減輕、肌肉流失。","c":"16.3","f":"慢性支氣管炎（黏液過多、慢性咳痰）＋肺氣腫；呼吸做功增加、慢性發炎 → 靜止能量消耗增加、食慾下降、肌肉流失（肺部惡病質）。","e":"營養重點：足夠熱量與高蛋白、少量多餐（飽脹會壓迫橫膈）、<b>避免過度餵食</b>（熱量過多產生較多 CO₂ 加重呼吸負擔）；醣類的呼吸商（1.0）高於脂肪（0.7），有 CO₂ 滯留的病人可酌量提高脂肪比例。補充維生素 D、鈣以防類固醇造成的骨質流失。","m":"<b>COPD＝吐不出來＋吃不夠＋肌肉流失</b>。","en":"COPD=chronic obstructive pulmonary disease|慢性阻塞性肺病;chronic bronchitis|慢性支氣管炎;pulmonary cachexia|肺部惡病質;respiratory quotient|呼吸商;overfeeding|過度餵食"},
"fibrosis":{"t":"肺纖維化 pulmonary fibrosis","d":"肺組織被結締組織取代，順應性下降，屬限制性肺病；可由石綿、矽塵或不明原因造成。","c":"16.3","e":"職業病：石綿肺、矽肺（礦工）、煤工塵肺；部分化療與放射治療也會引起。","f":"纖維母細胞增生、膠原沉積 → 肺變硬 → 順應性下降、肺容積變小；肺泡壁增厚 → 擴散距離變長 → 運動時更明顯缺氧。呼吸淺而快。","m":"<b>纖維化＝肺變硬，吸不進去</b>。","en":"pulmonary fibrosis|肺纖維化;asbestosis|石綿肺;silicosis|矽肺;decreased compliance|順應性下降"},
"partialp":{"t":"分壓 partial pressure","d":"混合氣體中某一氣體貢獻的壓力＝總壓 × 該氣體比例（道耳吞定律）；氣體由高分壓擴散到低分壓。","c":"16.4","e":"海平面大氣壓 760 mmHg，O₂ 占 21% → PO₂ 約 159 mmHg。到了肺泡因為加了水蒸氣（47 mmHg）並混入 CO₂，PO₂ 約 105。高山上大氣壓降低，雖然 O₂ 仍是 21%，PO₂ 卻下降。","f":"氣體交換方向只看分壓差：肺泡 PO₂ 105 → 靜脈血 40（O₂ 進血）；靜脈血 PCO₂ 46 → 肺泡 40（CO₂ 出血）。","m":"<b>比例不變，總壓降了分壓就降</b>。","en":"partial pressure|分壓;PO₂|氧分壓;PCO₂|二氧化碳分壓;760 mmHg|760 毫米汞柱"},
"dalton":{"t":"道耳吞定律、亨利定律","d":"<b>道耳吞</b>：總壓＝各分壓之和。<b>亨利</b>：溶解在液體中的氣體量與分壓及溶解度成正比（CO₂ 溶解度約 O₂ 的 20 倍）。","c":"16.4","f":"道耳吞定律用來算各氣體分壓；亨利定律解釋氣體溶入血液的量：O₂ 溶解度低，所以絕大部分要靠血紅素運送；CO₂ 溶解度高，所以 PCO₂ 差只有 6 mmHg 也能交換得很好。","e":"潛水夫病：深水高壓時大量氮氣溶入血液，上升太快壓力驟降 → 氮氣形成氣泡阻塞血管（像打開汽水）。","m":"<b>道耳吞算分壓、亨利算溶解量</b>。","en":"Dalton's law|道耳吞定律;Henry's law|亨利定律;solubility|溶解度;decompression sickness|減壓病"},
"abg":{"t":"動脈血氣 arterial blood gas","d":"測量動脈血的 PO₂（約 100）、PCO₂（約 40）、pH（約 7.40）、HCO₃⁻（約 24）；評估換氣與酸鹼。","c":"16.4、16.8","f":"判讀順序：①pH 看酸或鹼；②PCO₂ 異常方向與 pH 一致 → 呼吸性；③HCO₃⁻ 異常方向與 pH 一致 → 代謝性；④另一個是否反向改變 → 代償。","e":"重症營養支持時要看血氣：全靜脈營養若含過多氯（醋酸鹽太少）可能造成代謝性酸中毒。","m":"<b>pH 7.4、PCO₂ 40、HCO₃⁻ 24、PO₂ 100</b>。","en":"arterial blood gas|動脈血氣;PaO₂|動脈血氧分壓;PaCO₂|動脈血二氧化碳分壓;bicarbonate|碳酸氫根"},
"vq":{"t":"通氣—灌流配合 V/Q","d":"肺泡換氣量與血流量的比值（約 0.8）；缺氧時肺小動脈收縮，把血導向通氣好的區域（與體循環相反）。","c":"16.4","f":"站立時肺尖通氣與血流都較少，但血流少得更多 → V/Q 高；肺底則 V/Q 低。V/Q 不配合是缺氧最常見的原因：肺栓塞（有通氣沒血流＝死腔）、肺炎或痰阻塞（有血流沒通氣＝分流）。","m":"<b>肺血管遇缺氧收縮，體血管遇缺氧擴張</b>。","en":"ventilation-perfusion ratio|通氣-灌流比;V/Q mismatch|通氣灌流不配合;hypoxic pulmonary vasoconstriction|缺氧性肺血管收縮;shunt|分流"},
"respcenter":{"t":"呼吸中樞 respiratory centers","d":"延腦（背側呼吸群主吸氣、腹側呼吸群含節律產生者）自動產生節律；橋腦（呼吸調節中樞、長吸中樞）修飾。","c":"16.5","w":"腦幹：延腦（背側、腹側呼吸群）與橋腦。","f":"延腦腹側的前包欽格複合體是節律產生者；背側呼吸群整合周邊感受器訊息並驅動吸氣。橋腦調整吸氣長短與呼吸平順。大腦皮質可以暫時自主控制（憋氣、說話），但 CO₂ 累積後會被強迫恢復呼吸。","e":"嗎啡類藥物、酒精、安眠藥抑制延腦呼吸中樞，過量致死原因常是呼吸停止。","m":"<b>延腦定節律、橋腦修飾、皮質能暫時插手</b>。","en":"respiratory centers|呼吸中樞;dorsal respiratory group|背側呼吸群;ventral respiratory group|腹側呼吸群;pre-Bötzinger complex|前包欽格複合體"},
"centralchemo":{"t":"中樞化學感受器 central chemoreceptors","d":"位於延腦腹側；血中 CO₂ 穿過血腦障壁在腦脊髓液生成 H⁺ 而刺激它；平常調控呼吸最主要的機制。","c":"16.5","f":"CO₂ 能自由穿過血腦障壁，但 H⁺ 不能 → CO₂ 在腦脊髓液中與水生成碳酸 → H⁺ → 刺激感受器 → 增加換氣。腦脊髓液緩衝能力弱，所以對 CO₂ 變化非常敏感。","e":"長期 CO₂ 滯留的 COPD 病人，中樞感受器會「習慣」高 CO₂，改靠低 O₂ 驅動呼吸，所以給氧時要控制濃度。","m":"<b>中樞感受器其實是看 CO₂（經 H⁺）</b>。","en":"central chemoreceptors|中樞化學感受器;medulla oblongata|延腦;cerebrospinal fluid H⁺|腦脊髓液氫離子;CO₂ retention|二氧化碳滯留"},
"periphchemo":{"t":"周邊化學感受器 peripheral chemoreceptors","d":"<b>頸動脈體</b>（頸總動脈分叉，舌咽神經）與<b>主動脈體</b>（主動脈弓，迷走神經）；感測 PO₂↓（&lt; 約 60）、PCO₂↑、H⁺↑。國考考過位置。","m":"<b>周邊看 O₂ 與血中 H⁺；中樞看 CO₂</b>。","c":"16.5","f":"周邊化學感受器對 PO₂ 降低特別敏感，但要降到約 60 mmHg 以下才明顯反應（此時血紅素飽和度開始陡降）；也對代謝性酸中毒（H⁺ 增加）反應，因為血中 H⁺ 不能進腦。","en":"peripheral chemoreceptors|周邊化學感受器;hypoxemia|低血氧;PO₂ below 60 mmHg|氧分壓低於 60"},
"carotidbody":{"t":"頸動脈體、主動脈體","d":"<b>頸動脈體</b>：頸總動脈分叉處的小團化學感受細胞（舌咽神經），最重要的周邊化學感受器。<b>主動脈體</b>：主動脈弓附近（迷走神經）。","c":"16.5","w":"頸動脈體：頸總動脈分成內、外頸動脈的分叉處。主動脈體：主動脈弓附近。","f":"血流量極大（相對自身大小），所以能即時偵測動脈血的變化。注意不要與同位置的壓力感受器（頸動脈竇、主動脈弓）混淆：「體」測化學、「竇／弓」測壓力。","m":"<b>頸動脈「體」測化學，頸動脈「竇」測壓力</b>。","en":"carotid bodies|頸動脈體;aortic bodies|主動脈體;glossopharyngeal nerve|舌咽神經;vagus nerve|迷走神經"},
"heringbreuer":{"t":"赫鮑二氏反射 Hering-Breuer reflex","d":"肺過度膨脹時，呼吸道伸張受器經迷走神經抑制吸氣，防止過度膨脹。","c":"16.5","f":"成人平靜呼吸時作用不大，主要在潮氣容積很大時（約 3 倍以上，如運動）啟動；嬰兒較重要。","n":"19 世紀德國生理學家 Ewald Hering 與 Josef Breuer 發現。","m":"<b>吸太飽 → 迷走神經喊停</b>。","en":"Hering-Breuer reflex|赫鮑二氏反射;inflation reflex|充氣反射;stretch receptors|伸張受器"},
"hyperventilation":{"t":"過度換氣、換氣不足","d":"<b>過度換氣</b>：換氣超過代謝需要，PCO₂↓ → 呼吸性鹼中毒。<b>換氣不足</b>：PCO₂↑ → 呼吸性酸中毒。","c":"16.5、16.8","e":"焦慮時過度換氣 → CO₂ 下降 → 腦血管收縮（頭暈）、血中游離鈣減少（手腳麻、抽筋）；以前用紙袋回吸，現在建議放慢呼吸。","f":"判斷看 PCO₂，不是看呼吸快慢：運動時呼吸變快但 PCO₂ 不變，所以不算過度換氣。","m":"<b>過度換氣＝吹掉太多 CO₂ → 鹼</b>。","en":"hyperventilation|過度換氣;hypoventilation|換氣不足;hypocapnia|低碳酸血症;hypercapnia|高碳酸血症"},
"oxyhb":{"t":"氧合、去氧血紅素","d":"<b>氧合血紅素</b>：結合 O₂，鮮紅。<b>去氧血紅素</b>：放出 O₂，暗紅，較能緩衝 H⁺ 與攜帶 CO₂。","c":"16.6","f":"每個血紅素有 4 個血基質，每個含 1 個 Fe²⁺，共能結合 4 個 O₂；結合一個後構形改變，後面的更容易結合（協同作用）→ S 形曲線。每公克血紅素攜帶約 1.34 mL O₂。","e":"血紅素合成需要鐵、維生素 B6（ALA 合成酶）、蛋白質；缺鐵時攜氧能力下降。","m":"<b>4 個血基質、4 個 O₂、一個帶一個</b>。","en":"oxyhemoglobin|氧合血紅素;deoxyhemoglobin|去氧血紅素;cooperative binding|協同結合;oxygen-carrying capacity|攜氧能力"},
"methb":{"t":"變性血紅素 methemoglobin","d":"血基質鐵被氧化成 Fe³⁺，無法結合 O₂；可由某些藥物或過多亞硝酸鹽引起。","c":"16.6","f":"正常紅血球每天有少量 Fe²⁺ 被氧化，靠細胞色素 b5 還原酶（用 NADH）還原回 Fe²⁺。氧化壓力超過時累積 → 皮膚發紺、血呈巧克力色；治療用亞甲藍，維生素 C 也有還原作用。","e":"嬰兒（尤其 6 個月以下）喝到硝酸鹽含量高的井水泡的奶，或吃大量含硝酸鹽的蔬菜泥，可能造成「藍嬰症」；嬰兒還原酶活性低、HbF 較易被氧化。","m":"<b>Fe³⁺ 不能帶氧</b>。","en":"methemoglobin|變性血紅素;ferric iron|三價鐵;methemoglobinemia|變性血紅素血症;blue baby syndrome|藍嬰症;nitrate|硝酸鹽;methylene blue|亞甲藍"},
"carboxyhb":{"t":"碳氧血紅素、一氧化碳中毒","d":"CO 與血紅素的親和力約為 O₂ 的 210 倍，佔據結合位並使剩餘 O₂ 不易釋放；呈鮮紅色，脈搏血氧計可能誤判。治療給高濃度或高壓氧。","c":"16.6","e":"冬天在密閉浴室使用燃氣熱水器、燒炭是常見原因；症狀頭痛、噁心、意識不清。抽菸者血中也有 5–10% 碳氧血紅素。","f":"CO 除了佔位，還讓剩下的血紅素更不肯放 O₂（曲線左移），所以缺氧比單純貧血更嚴重。","m":"<b>CO 黏 210 倍，又讓 O₂ 放不掉</b>。","en":"carboxyhemoglobin|碳氧血紅素;carbon monoxide poisoning|一氧化碳中毒;hyperbaric oxygen|高壓氧;pulse oximeter|脈搏血氧計"},
"odc":{"t":"氧合血紅素解離曲線 oxyhemoglobin dissociation curve","d":"S 形：肺（PO₂ 100）飽和約 97%；靜止組織（40）約 75%；上方平坦提供安全餘裕，下方陡峭利於釋氧。","c":"16.6","f":"上方平坦段：即使肺泡 PO₂ 從 100 降到 70，飽和度仍超過 90%（高山、輕度肺病的緩衝）。下方陡峭段：組織 PO₂ 稍降就能釋放大量 O₂（運動時肌肉 PO₂ 可降到 20，飽和度降到約 30%）。<b>右移</b>（釋氧多）：H⁺↑、CO₂↑、溫度↑、2,3-BPG↑。<b>左移</b>（抓得緊）：相反、HbF、CO。","m":"<b>右移 CADET：CO₂、Acid、DPG、Exercise、Temperature</b>。","en":"oxyhemoglobin dissociation curve|氧合血紅素解離曲線;sigmoidal|S 形;right shift|右移;left shift|左移;percent saturation|飽和百分比"},
"bohr":{"t":"波爾效應 Bohr effect","d":"H⁺ 增加（pH 下降）與 CO₂ 增加使血紅素對 O₂ 親和力下降、曲線右移，在活動組織釋放更多 O₂。","c":"16.6","f":"H⁺ 與 CO₂ 結合在血紅素上使構形改變，降低對 O₂ 的親和力。運動中的肌肉 CO₂ 多、乳酸多、溫度高 → 自動多放 O₂；在肺則 CO₂ 被排出 → 親和力回升、多抓 O₂。","n":"丹麥生理學家 Christian Bohr（物理學家 Niels Bohr 的父親）1904 年發現。","m":"<b>波爾：酸讓血紅素放氧</b>（何登則是放氧讓血紅素多帶 CO₂）。","en":"Bohr effect|波爾效應;decreased affinity|親和力下降;acidic pH|酸性 pH"},
"bpg":{"t":"2,3-BPG（2,3-DPG）","d":"紅血球糖解產生的中間產物，結合去氧血紅素的 β 鏈，降低 O₂ 親和力（右移）；貧血、高海拔時增加，庫存血減少。","c":"16.6","f":"紅血球沒有粒線體，靠糖解產生 ATP；糖解的 1,3-BPG 經支路轉成 2,3-BPG，嵌在去氧血紅素中間穩定它的去氧狀態。","e":"重度營養不良者重新進食（再餵食症候群）時血磷急降 → 2,3-BPG 與 ATP 合成不足 → 組織缺氧，是再餵食症候群危險的原因之一。庫存血輸大量時釋氧較差。","m":"<b>BPG 越多越放氧</b>。","en":"2,3-BPG=2,3-bisphosphoglycerate|2,3-雙磷酸甘油酸;2,3-DPG|2,3-雙磷酸甘油酸;refeeding syndrome|再餵食症候群;hypophosphatemia|低血磷"},
"hbf":{"t":"胎兒血紅素 HbF","d":"2α＋2γ 鏈，與 2,3-BPG 結合較弱，對 O₂ 親和力較高（左移），能從母體血液取得 O₂；出生後逐漸被 HbA 取代。","c":"16.6；第 20 章","f":"胎盤處母血與胎兒血不直接混合，胎兒靠 HbF 較高的親和力「搶」母體的 O₂；胎兒紅血球數目與血紅素濃度也較高。出生後約 6 個月大部分換成 HbA。","e":"新生兒紅血球大量破壞→生理性黃疸；之後鐵存量足夠用到約 4–6 個月，之後要從副食品補鐵。鐮刀型貧血用藥物增加 HbF 可減輕症狀。","m":"<b>γ 鏈不黏 BPG → 左移搶氧</b>。","en":"fetal hemoglobin|胎兒血紅素;HbF|胎兒血紅素;gamma chains|γ 鏈;higher oxygen affinity|較高的氧親和力"},
"sickle":{"t":"鐮刀型貧血 sickle-cell anemia","d":"β 鏈第 6 個胺基酸麩胺酸 → 纈胺酸（HbS），去氧時聚合使紅血球呈鐮刀狀，阻塞微血管並易溶血。","c":"16.6","f":"HbS 在去氧時聚合成長纖維 → 紅血球變形、僵硬 → 阻塞微血管（疼痛危機、器官梗塞）並被脾臟破壞（溶血）。帶因者（HbAS）對瘧疾有一定抵抗力，所以在非洲瘧疾流行區常見。","e":"溶血使紅血球更新快，需注意葉酸；脫水、缺氧、寒冷會誘發危機，要多喝水。","m":"<b>第 6 位 Glu → Val，帶負電變疏水</b>。","en":"sickle-cell anemia|鐮刀型貧血;HbS|鐮刀型血紅素;glutamic acid to valine|麩胺酸變纈胺酸;vaso-occlusive crisis|血管阻塞危機;malaria resistance|抗瘧疾"},
"thalassemia":{"t":"地中海型貧血 thalassemia","d":"α 或 β 鏈合成不足造成的小球性貧血；台灣帶因率約 6%，建議婚前或產前篩檢，帶因者不應盲目補鐵。","c":"16.6","f":"α 鏈或 β 鏈基因缺失或突變 → 珠蛋白鏈合成不平衡 → 多餘的鏈沉積破壞紅血球 → 小球性低色素貧血、溶血。重型需要定期輸血，會造成鐵過量，需要排鐵劑。","e":"與缺鐵性貧血一樣是小球性，但血清鐵蛋白正常或偏高；營養上不要自行補鐵，必要時補充葉酸；重型病人應避免高鐵食物與鐵強化食品，配茶可減少鐵吸收。","n":"希臘文 thalassa（海）＋ haima（血），最早在地中海沿岸發現。","m":"<b>地貧不缺鐵，補鐵反而傷</b>。","en":"thalassemia|地中海型貧血;alpha thalassemia|α 型地中海型貧血;beta thalassemia|β 型地中海型貧血;iron overload|鐵過量;iron chelation|排鐵治療"},
"carbaminohb":{"t":"胺甲醯血紅素 carbaminohemoglobin","d":"CO₂ 與血紅素蛋白質部分的胺基結合的形式，約占 CO₂ 運送的 20%。","c":"16.7","f":"CO₂ 的三種運送方式：約 70% 變成 HCO₃⁻、約 20% 胺甲醯血紅素、約 10% 直接溶解。去氧血紅素較容易形成胺甲醯血紅素（何登效應）。","m":"<b>70% 碳酸氫根、20% 血紅素、10% 溶解</b>。","en":"carbaminohemoglobin|胺甲醯血紅素;CO₂ transport|二氧化碳運送;dissolved CO₂|溶解的二氧化碳"},
"chlorideshift":{"t":"氯轉移 chloride shift","d":"組織中紅血球內產生的 HCO₃⁻ 移到血漿，Cl⁻ 移入補位；在肺中反向（逆氯轉移）。","c":"16.7","f":"組織：CO₂ 進紅血球 → 碳酸酐酶 → H₂CO₃ → H⁺（被血紅素緩衝）＋ HCO₃⁻ → HCO₃⁻ 經 Band 3 交換蛋白出去、Cl⁻ 進來，維持電中性。肺：反向進行，HCO₃⁻ 回到紅血球變回 CO₂ 呼出。","e":"所以靜脈血紅血球的 Cl⁻ 較多、體積稍大。","m":"<b>HCO₃⁻ 出、Cl⁻ 進</b>。","en":"chloride shift|氯轉移;reverse chloride shift|逆氯轉移;band 3 protein|第三帶蛋白;carbonic anhydrase|碳酸酐酶"},
"haldane":{"t":"何登效應 Haldane effect","d":"去氧血紅素比氧合血紅素更能攜帶 CO₂ 與 H⁺；組織放出 O₂ 有助於帶走 CO₂，在肺則相反。","c":"16.7","f":"去氧血紅素是較好的 H⁺ 緩衝者，也較容易結合 CO₂；組織中 O₂ 被釋放後，血液自動能多帶 CO₂。在肺中血紅素與 O₂ 結合 → 釋放 H⁺ 與 CO₂ → 有利於 CO₂ 排出。","n":"英國生理學家 John Scott Haldane 提出。","m":"<b>放了 O₂ 就能多帶 CO₂</b>。","en":"Haldane effect|何登效應;deoxygenated blood carries more CO₂|去氧血帶更多二氧化碳"},
"acidbase":{"t":"酸鹼平衡 acid-base balance","d":"血液 pH 維持 7.35–7.45；靠緩衝系統、肺（調 CO₂）與腎（調 HCO₃⁻）；HCO₃⁻：CO₂ 約 20：1。","c":"16.8；第 17 章","f":"三道防線：①化學緩衝（秒）：碳酸氫鹽、磷酸鹽、蛋白質（血紅素）；②呼吸（分鐘）：調整 CO₂ 排出；③腎臟（數小時到數天）：排 H⁺、回收與新生 HCO₃⁻、產生氨。","e":"高蛋白、高肉類飲食產生較多酸（含硫胺基酸 → 硫酸）；蔬果富含鉀與有機酸鹽，代謝後偏鹼。慢性腎病時酸排除困難，常需補充碳酸氫鈉。","m":"<b>緩衝最快、肺次之、腎最慢但最徹底</b>。","en":"acid-base balance|酸鹼平衡;buffer systems|緩衝系統;respiratory compensation|呼吸代償;renal compensation|腎臟代償;dietary acid load|飲食酸負荷"},
"volatileacid":{"t":"揮發性酸、非揮發性酸","d":"<b>揮發性</b>：碳酸，可變成 CO₂ 由肺排出。<b>非揮發性</b>（固定酸）：乳酸、酮體、硫酸、磷酸，由腎排出。","c":"16.8","f":"揮發性酸每天約 13,000–20,000 mmol（以 CO₂ 形式），量大但肺能快速排除。非揮發性酸每天約 50–100 mmol，來自含硫胺基酸、磷蛋白與磷脂、不完全氧化的醣與脂肪，只能由腎排除。","m":"<b>揮發的走肺、固定的走腎</b>。","en":"volatile acid|揮發性酸;nonvolatile acid|非揮發性酸;fixed acid|固定酸;carbonic acid|碳酸;sulfuric acid|硫酸"},
"hh":{"t":"韓德森—哈索巴赫方程","d":"pH＝6.1＋log（[HCO₃⁻]／0.03 × PCO₂）；HCO₃⁻ 24、PCO₂ 40 時 pH 為 7.4。","c":"16.8","f":"說明 pH 取決於 HCO₃⁻（腎控制）與 PCO₂（肺控制）的「比值」，而不是個別數值；只要比值維持 20：1，pH 就是 7.4，這就是代償的原理。","n":"美國生化學家 Lawrence Henderson 與丹麥化學家 Karl Hasselbalch。","m":"<b>pH ∝ 腎／肺（HCO₃⁻／CO₂）</b>。","en":"Henderson-Hasselbalch equation|韓德森-哈索巴赫方程;pKa 6.1|pKa 6.1;20 to 1 ratio|20 比 1"},
"respacid":{"t":"呼吸性酸中毒、鹼中毒","d":"<b>呼吸性酸中毒</b>：換氣不足 → PCO₂↑（COPD、呼吸抑制）。<b>呼吸性鹼中毒</b>：過度換氣 → PCO₂↓（焦慮、高海拔）。腎臟代償。","c":"16.8","f":"急性時只有化學緩衝，pH 變化大；慢性時腎臟代償：呼吸性酸中毒 → 腎多保留 HCO₃⁻；呼吸性鹼中毒 → 腎多排 HCO₃⁻。","e":"重症呼吸衰竭病人給予過多熱量（尤其大量葡萄糖）會增加 CO₂ 產生，可能加重 CO₂ 滯留、延遲脫離呼吸器。","m":"<b>呼吸性：PCO₂ 與 pH 反方向</b>（PCO₂ 升 → pH 降）。","en":"respiratory acidosis|呼吸性酸中毒;respiratory alkalosis|呼吸性鹼中毒;compensation|代償;CO₂ retention|二氧化碳滯留"},
"metacid":{"t":"代謝性酸中毒、鹼中毒","d":"<b>代謝性酸中毒</b>：HCO₃⁻↓（酮酸、乳酸、腹瀉、腎衰竭），過度換氣代償。<b>代謝性鹼中毒</b>：HCO₃⁻↑（嘔吐、制酸劑），換氣減少代償。","c":"16.8","f":"代謝性酸中毒可用陰離子間隙（Na⁺ −（Cl⁻＋HCO₃⁻），正常約 8–12）區分：間隙增加（酮酸、乳酸、腎衰竭、甲醇中毒）；間隙正常（腹瀉流失 HCO₃⁻、腎小管酸中毒）。","e":"嚴重嘔吐流失胃酸（HCl）→ 代謝性鹼中毒＋低鉀；長期腹瀉流失 HCO₃⁻ → 代謝性酸中毒。生酮飲食、長時間禁食會使酮體增加。","m":"<b>代謝性：HCO₃⁻ 與 pH 同方向；吐鹼、瀉酸</b>。","en":"metabolic acidosis|代謝性酸中毒;metabolic alkalosis|代謝性鹼中毒;anion gap|陰離子間隙;vomiting|嘔吐;diarrhea|腹瀉"},
"dka":{"t":"糖尿病酮酸中毒 diabetic ketoacidosis","d":"胰島素嚴重不足時脂肪大量分解產生酮體，造成代謝性酸中毒、高血糖、脫水；呼吸深快（庫斯毛耳呼吸）、口氣有丙酮味。","c":"16.8；第 19 章","f":"胰島素不足＋升糖素過多 → 脂肪大量分解 → 肝臟產生乙醯乙酸、β-羥基丁酸（酮酸）→ 代謝性酸中毒；高血糖 → 滲透性利尿 → 嚴重脫水、鉀流失（但血鉀可能一開始偏高，因為酸中毒讓鉀從細胞出來）。","e":"多見於第 1 型糖尿病、感染時未注射胰島素。治療：輸液、胰島素、補鉀。和生酮飲食的「營養性酮症」不同：後者酮體濃度低、胰島素仍有作用、pH 正常。","m":"<b>沒胰島素 → 燒脂肪 → 酮酸 → 酸中毒</b>。","en":"DKA=diabetic ketoacidosis|糖尿病酮酸中毒;ketone bodies|酮體;nutritional ketosis|營養性酮症;fruity breath|水果味口氣"},
"kussmaul":{"t":"庫斯毛耳呼吸 Kussmaul breathing","d":"代謝性酸中毒時深而快的呼吸，呼出 CO₂ 以代償。","c":"16.8","n":"19 世紀德國醫師 Adolf Kussmaul 描述糖尿病昏迷病人的呼吸。","e":"出現在糖尿病酮酸中毒、尿毒症、嚴重乳酸中毒。","m":"<b>酸中毒 → 深大呼吸把 CO₂ 吹掉</b>。","en":"Kussmaul breathing|庫斯毛耳呼吸;deep rapid breathing|深而快的呼吸;metabolic acidosis|代謝性酸中毒"},
"hyperpnea":{"t":"運動換氣增加 exercise hyperpnea","d":"運動時換氣隨代謝等比例增加，動脈血氣幾乎不變；推測來自大腦前饋與肌肉關節的回饋。","c":"16.9","f":"與過度換氣不同：運動換氣增加是配合 CO₂ 產生量增加，所以 PCO₂、PO₂、pH 幾乎不變。超過無氧閾值後乳酸增加，換氣才會超過比例增加。","e":"呼吸商（RQ＝CO₂ 產生／O₂ 消耗）可看出燃料：醣類 1.0、蛋白質約 0.8、脂肪 0.7；間接熱量測定就是用 O₂、CO₂ 估算能量消耗與燃料比例。","m":"<b>運動喘＝等比例增加，不是過度換氣</b>。","en":"exercise hyperpnea|運動換氣增加;RQ=respiratory quotient|呼吸商;indirect calorimetry|間接熱量測定;anaerobic threshold|無氧閾值"},
"acclimat":{"t":"高海拔適應 acclimatization","d":"PO₂↓ → 換氣↑（呼吸性鹼中毒）→ 腎排 HCO₃⁻；2,3-BPG↑；EPO → 紅血球↑（需鐵）；數天至數週完成。","c":"16.9","f":"數小時：換氣增加（周邊化學感受器）。數天：腎排 HCO₃⁻ 矯正鹼中毒、讓換氣能持續增加；2,3-BPG 增加。數週：腎分泌紅血球生成素 → 紅血球與血紅素增加；肌肉微血管與粒線體增加。","e":"上高山前與在高山上要注意鐵與熱量攝取，高山上食慾常下降、基礎代謝上升；多喝水，因為乾冷空氣與換氣增加使水分流失多。","m":"<b>先多喘、再改腎、後造血</b>。","en":"acclimatization|高海拔適應;high altitude|高海拔;erythropoietin|紅血球生成素;polycythemia|紅血球增多"},
"ams":{"t":"高山症 acute mountain sickness","d":"快速上升到高海拔出現的頭痛、失眠、噁心；嚴重時高海拔肺水腫或腦水腫，最重要處置是下降高度；乙醯唑胺可預防。","c":"16.9","f":"缺氧使腦血管擴張、血管通透性增加 → 腦水腫（頭痛、意識改變、步態不穩）；缺氧性肺血管收縮不均 → 肺水腫（咳嗽、呼吸困難、粉紅色泡沫痰）。","e":"台灣登玉山、雪山（3,000 公尺以上）就可能發生；預防：緩慢上升、高處活動低處睡、多喝水、避免酒精。乙醯唑胺是碳酸酐酶抑制劑，使尿中排 HCO₃⁻、造成輕度代謝性酸中毒而刺激換氣。","m":"<b>高山症最好的藥是往下走</b>。","en":"AMS=acute mountain sickness|高山症;HAPE=high-altitude pulmonary edema|高海拔肺水腫;HACE=high-altitude cerebral edema|高海拔腦水腫;acetazolamide|乙醯唑胺"}});
Object.assign(GL_ALIAS,{"換氣":"ventilation","肺泡":"alveoli","第一型肺泡細胞":"alvcell","第二型肺泡細胞":"alvcell","傳導區":"condzone","呼吸區":"condzone","黏液纖毛電扶梯":"mucocil","胸膜":"pleura","胸膜腔":"pleura","氣胸":"pneumothorax","波以耳定律":"boyle","肺內壓":"intrapulm","胸膜內壓":"intrapulm","順應性":"compliance","表面張力":"surfacetension","拉普拉斯定律":"surfacetension","表面活性劑":"surfactant","呼吸窘迫症候群":"rds","橫膈":"diaphragm","膈神經":"diaphragm","外肋間肌":"intercostal","內肋間肌":"intercostal","潮氣容積":"tidal","肺活量":"vc","殘氣容積":"rv","功能肋餘容量":"frc","吸氣儲備容積":"lungvol","呼氣儲備容積":"lungvol","總肺容量":"lungvol","死腔":"deadspace","解剖死腔":"deadspace","FEV₁":"fev1","氣喘":"asthma","肺氣腫":"emphysema","COPD":"copd","慢性阻塞性肺病":"copd","肺纖維化":"fibrosis","分壓":"partialp","道耳吞定律":"dalton","亨利定律":"dalton","血氣":"abg","動脈血氣":"abg","通氣—灌流":"vq","呼吸中樞":"respcenter","延腦呼吸中樞":"respcenter","中樞化學感受器":"centralchemo","周邊化學感受器":"periphchemo","頸動脈體":"carotidbody","主動脈體":"carotidbody","赫鮑二氏反射":"heringbreuer","過度換氣":"hyperventilation","換氣不足":"hyperventilation","氧合血紅素":"oxyhb","去氧血紅素":"oxyhb","變性血紅素":"methb","碳氧血紅素":"carboxyhb","一氧化碳":"carboxyhb","解離曲線":"odc","氧合血紅素解離曲線":"odc","波爾效應":"bohr","2,3-BPG":"bpg","胎兒血紅素":"hbf","鐮刀型貧血":"sickle","地中海型貧血":"thalassemia","胺甲醯血紅素":"carbaminohb","氯轉移":"chlorideshift","何登效應":"haldane","酸鹼平衡":"acidbase","揮發性酸":"volatileacid","非揮發性酸":"volatileacid","韓德森—哈索巴赫":"hh","呼吸性酸中毒":"respacid","呼吸性鹼中毒":"respacid","代謝性酸中毒":"metacid","代謝性鹼中毒":"metacid","糖尿病酮酸中毒":"dka","酮酸中毒":"dka","庫斯毛耳呼吸":"kussmaul","運動換氣增加":"hyperpnea","高海拔適應":"acclimat","高山症":"ams"});

/* ---- end ch16 ---- */
